/// KT-1750 — a file turned into a symlink (git's `T`) is delivered as a
/// modification, not refused as an unsupported status.
#[cfg(unix)] // creates symlinks through std::os::unix
#[test]
fn a_file_turned_into_a_symlink_is_delivered_as_modified() {
    let repo = init_repo();
    let dir = repo.path();
    std::fs::write(dir.join("config.txt"), "real file").unwrap();
    std::fs::write(dir.join("target.txt"), "target").unwrap();
    git(dir, &["add", "."]);
    git(dir, &["commit", "-m", "base"]);
    let base = git_rev(dir, "HEAD");

    std::fs::remove_file(dir.join("config.txt")).unwrap();
    std::os::unix::fs::symlink("target.txt", dir.join("config.txt")).unwrap();
    git(dir, &["add", "config.txt"]);
    git(dir, &["commit", "-m", "file becomes a symlink"]);
    let raw = git(
        dir,
        &["diff", "--name-status", "--no-renames", &base, "HEAD"],
    );
    assert!(
        String::from_utf8_lossy(&raw.stdout).starts_with("T\t"),
        "the fixture must be a git type change: {raw:?}"
    );

    let facts = delivery_git_facts_from_repo(dir.to_path_buf(), &base, None)
        .expect("a type change is a deliverable change");
    assert_eq!(facts.files_touched.len(), 1);
    assert_eq!(facts.files_touched[0].path, "config.txt");
    assert_eq!(facts.files_touched[0].kind, FileChangeKind::Modified);
}

/// KT-1750 — an untracked `.DS_Store` does not stop a delivery.
#[tokio::test]
async fn an_untracked_ds_store_does_not_block_the_delivery_check() {
    let repo = init_repo();
    let dir = repo.path();
    let base = git_rev(dir, "HEAD");
    std::fs::write(dir.join("work.txt"), "work").unwrap();
    git(dir, &["add", "work.txt"]);
    git(dir, &["commit", "-m", "work"]);
    std::fs::write(dir.join(".DS_Store"), "junk").unwrap();
    assert!(worktree::worktree_dirty_files(dir).unwrap().is_empty());
    let facts = delivery_git_facts_from_repo(dir.to_path_buf(), &base, None).unwrap();
    assert_eq!(facts.files_touched.len(), 1);
}

/// KT-1750 — the brief names the sign-off only where the project signs off,
/// whatever the transport and language.
#[test]
fn worker_brief_names_the_sign_off_only_when_the_project_signs_off() {
    for lang in [RoomLang::Fr, RoomLang::En] {
        for (can_run_shell, projection) in [(true, true), (true, false)] {
            let brief = |signoff: bool| {
                worker_brief_markdown_in(
                    lang,
                    "KT-1750",
                    "Identity",
                    "Objective",
                    &[],
                    "/wt/kt1750",
                    "kronn/task/KT-1750",
                    "abc1234",
                    can_run_shell,
                    projection,
                    None,
                    signoff,
                )
            };
            let case = format!("{lang:?} shell={can_run_shell} projection={projection}");
            let signed = brief(true);
            let unsigned = brief(false);
            assert!(
                signed.contains("sign-off") || signed.contains("git commit -s"),
                "{case}: the signed brief names the sign-off: {signed}"
            );
            for forbidden in ["git commit -s", "--signoff", "sign-off"] {
                assert!(
                    !unsigned
                        .replace("sans sign-off (ce projet n'en utilise pas)", "")
                        .replace("without a sign-off (this project does not use one)", "")
                        .contains(forbidden),
                    "{case}: the unsigned brief must not name `{forbidden}`: {unsigned}"
                );
            }
        }
    }
}

/// KT-1751 — the Rust lint gate (`cargo fmt`, `cargo clippy`) is for a
/// project that builds with Cargo: a worker of a PHP/Node/iOS project, or of
/// one whose toolchain Kronn does not know, is never told to run it.
#[test]
fn the_cargo_gate_text_is_only_for_projects_that_build_with_cargo() {
    let brief = |lang, path: &str| {
        worker_brief_markdown_in(
            lang,
            "KT-1751",
            "Gate",
            "Objective",
            &[],
            path,
            "kronn/task/KT-1751",
            "abc1234",
            true,
            true,
            None,
            true,
        )
    };
    let php = tempfile::tempdir().unwrap();
    std::fs::write(php.path().join("composer.json"), "{}").unwrap();
    std::fs::write(php.path().join("Makefile"), "").unwrap();
    let rust = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(rust.path().join("backend")).unwrap();
    std::fs::write(rust.path().join("backend/Cargo.toml"), "").unwrap();
    std::fs::write(rust.path().join("Makefile"), "").unwrap();
    let php = php.path().to_string_lossy().into_owned();
    let rust = rust.path().to_string_lossy().into_owned();

    for lang in [RoomLang::En, RoomLang::Fr] {
        let other = brief(lang, &php);
        assert!(!other.contains("cargo clippy"), "{other}");
        assert!(!other.contains("cargo fmt"), "{other}");
        assert!(!other.contains("cargo test --lib"), "{other}");
        // Still told how to evidence a result, and where the conventions are.
        assert!(other.contains("exit code") || other.contains("code de sortie"));
        assert!(other.contains("task_exec_deliver"), "{other}");

        let kept = brief(lang, &rust);
        assert!(kept.contains("cargo clippy --all-targets -- -D warnings"));
        assert!(kept.contains("cargo fmt --check"));
        // Y2: a worktree whose toolchains Kronn does not know (Python, Go,
        // Gradle) is not given the cargo gate either.
        let unknown = brief(lang, "/wt/unknown");
        assert!(!unknown.contains("cargo clippy"), "{unknown}");
    }
}

/// KT-1747 — the brief carries a "Project conventions" section composed from
/// the toolchains found in the worktree (any project), in the room's
/// language, and none for a worktree that has none.
#[test]
fn worker_brief_composes_project_conventions_from_the_detected_toolchains() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("composer.json"), "{}").unwrap();
    std::fs::create_dir_all(dir.path().join("assets/front")).unwrap();
    std::fs::write(dir.path().join("assets/front/package.json"), "{}").unwrap();
    std::fs::write(dir.path().join("assets/front/yarn.lock"), "").unwrap();
    std::fs::write(dir.path().join("Makefile"), "").unwrap();
    let worktree = dir.path().to_string_lossy().into_owned();
    let brief = |lang, path: &str| {
        worker_brief_markdown_in(
            lang,
            "KT-1747",
            "Conventions",
            "Objective",
            &[],
            path,
            "kronn/task/KT-1747",
            "abc1234",
            true,
            true,
            None,
            true,
        )
    };

    let english = brief(RoomLang::En, &worktree);
    assert!(english.contains("## Project conventions"), "{english}");
    assert!(
        english.contains("- composer at `.` (dependencies in `vendor/`)"),
        "{english}"
    );
    assert!(
        english.contains("- yarn at `assets/front` (dependencies in `assets/front/node_modules/`)"),
        "{english}"
    );
    assert!(english.contains("- make at `.`"), "{english}");
    // Placed before the tests the worker runs.
    assert!(
        english.find("## Project conventions") < english.find("## Tests"),
        "{english}"
    );

    let french = brief(RoomLang::Fr, &worktree);
    assert!(french.contains("## Conventions du projet"), "{french}");
    assert!(
        french.contains("- composer à `.` (dépendances dans `vendor/`)"),
        "{french}"
    );

    let none = brief(RoomLang::En, "/wt/no-such-worktree");
    assert!(!none.contains("Project conventions"), "{none}");
    assert!(!brief(RoomLang::Fr, "/wt/no-such-worktree").contains("Conventions du projet"));
}

/// KT-1669 — the brief asks a lane to keep only its own citations green and
/// says the integration settles a citation-only conflict, whatever the
/// transport and language.
#[test]
fn worker_brief_leaves_citation_only_conflicts_to_the_integration() {
    // KT-1747: carried by a project whose docs carry `[src:]` citations.
    let worktree = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(worktree.path().join("docs")).unwrap();
    std::fs::write(
        worktree.path().join("docs/guide.md"),
        "The entry point [src: file: src/main.rs:1].\n",
    )
    .unwrap();
    let worktree_path = worktree.path().to_string_lossy().into_owned();
    for lang in [RoomLang::Fr, RoomLang::En] {
        for (can_run_shell, projection) in [(true, true), (true, false), (false, true)] {
            let brief = worker_brief_markdown_in(
                lang,
                "KT-1669",
                "Citations",
                "Objective",
                &[],
                &worktree_path,
                "kronn/task/KT-1669",
                "abc1234",
                can_run_shell,
                projection,
                None,
                true,
            );
            let (heading, own_gate, not_target) = match lang {
                RoomLang::Fr => (
                    "## Citations de documentation",
                    "c'est ta propre porte",
                    "Ne ré-ancre pas les citations des docs que tu n'as pas modifiés",
                ),
                RoomLang::En => (
                    "## Doc citations",
                    "that is your own gate",
                    "Do not re-anchor the citations of docs you did not edit",
                ),
            };
            let (shift, broken_for_good) = match lang {
                RoomLang::Fr => (
                    "ton décalage de code a seulement déplacée",
                    "Une citation que ton changement casse pour de bon",
                ),
                RoomLang::En => (
                    "your code shift only moved",
                    "A citation your change breaks for good",
                ),
            };
            for needle in [heading, own_gate, not_target, shift, broken_for_good] {
                assert!(brief.contains(needle), "missing `{needle}`: {brief}");
            }
            assert!(
                !brief.contains("make docs-reanchor"),
                "a lane is never asked to run the repository-wide re-anchor: {brief}"
            );
        }
    }
}

#[test]
fn worker_briefs_make_human_arbitration_and_parent_milestones_transport_aware() {
    let joined_cli = worker_brief_markdown(
        "KT-635",
        "Arbitrages",
        "Modifier un contrat",
        &[],
        "/wt/joined",
        "kronn/task/KT-635",
        "abc1234",
        true,
        false,
        None,
    );
    for needle in [
        "## Arbitrages humains et jalons parent",
        "décision produit",
        "disc_question_list",
        "disc_append",
        "`kronn-question`",
        "`\"version\":1`",
        "pause ce seul périmètre",
        "Jalons parent factuels",
        "pas de miroir automatique",
    ] {
        assert!(
            joined_cli.contains(needle),
            "joined CLI must mention `{needle}`\n{joined_cli}"
        );
    }
    // The joined CLI's own human_arbitration section (just above) names
    // `disc_append`/`disc_question_list` as real tools it holds. Its parent-milestones
    // section must not invent a false "child room only" restriction: `disc_append`
    // actually accepts an explicit `disc_id` (it can target the parent once known via
    // `task_exec_status`), only `disc_question_list` is truly bound-only.
    assert!(
            !joined_cli.contains("ne déclare aucun outil de publication"),
            "joined CLI has disc_append/disc_question_list — must not claim it declares no publication tool: {joined_cli}"
        );
    assert!(
            !joined_cli.contains("jamais la room parente directement"),
            "joined CLI must not falsely restrict disc_append to the child room only — it accepts an explicit disc_id: {joined_cli}"
        );
    assert!(
        joined_cli.contains("task_exec_status") && joined_cli.contains("parent_discussion_id"),
        "joined CLI must name the real way to learn the authorized parent id: {joined_cli}"
    );
    assert!(
            joined_cli.contains("disc_id` explicite"),
            "joined CLI must state disc_append accepts an explicit disc_id, not child-only: {joined_cli}"
        );
    assert!(
        joined_cli.contains("borné à cette seule sous-discussion"),
        "joined CLI must state disc_question_list, not disc_append, is bound-only: {joined_cli}"
    );
    assert!(
            joined_cli.contains("ce ne sont pas") && joined_cli.contains("les seuls jalons possibles"),
            "joined CLI must state parent milestones are not limited to attach/review events: {joined_cli}"
        );

    let native_cli = worker_brief_markdown(
        "KT-635",
        "Arbitrages",
        "Modifier un contrat",
        &[],
        "/wt/native",
        "kronn/task/KT-635",
        "abc1234",
        true,
        true,
        None,
    );
    let generic_http = worker_brief_markdown(
        "KT-635",
        "Arbitrages",
        "Modifier un contrat",
        &[],
        "/wt/http",
        "kronn/task/KT-635",
        "abc1234",
        false,
        true,
        None,
    );
    let scope = TaskWorkerScope::PrelocalizedEdit {
        path: "backend/src/lib.rs".into(),
        start_line: 40,
        end_line: 44,
    };
    let prelocalized_http = worker_brief_markdown(
        "KT-635",
        "Arbitrages",
        "Modifier un contrat",
        &[],
        "/wt/prelocalized",
        "kronn/task/KT-635",
        "abc1234",
        false,
        true,
        Some(&scope),
    );
    // A bounded edit never arbitrates nor reports milestones: both
    // sections only cost a local worker context.
    assert!(
        !prelocalized_http.contains("## Arbitrages humains")
            && !prelocalized_http.contains("## Jalons parent"),
        "{prelocalized_http}"
    );
    for (name, brief) in [("native CLI", native_cli), ("generic HTTP", generic_http)] {
        assert!(
            brief.contains("demande au principal de relayer"),
            "{name}: {brief}"
        );
        assert!(
            brief.contains("ne décide jamais à la place de l'humain"),
            "{name}: {brief}"
        );
        assert!(brief.contains("pause ce seul périmètre"), "{name}: {brief}");
        assert!(
            brief.contains("## Jalons parent factuels"),
            "{name}: {brief}"
        );
        assert!(
            !brief.contains("Avant de solliciter une décision produit, appelle"),
            "{name}: {brief}"
        );
        // Native/HTTP hold no room-publication tool at all — unlike the joined CLI,
        // their parent-milestones text must say so plainly, and must never claim the
        // sub-discussion-scoped disc_append reach that only a joined CLI actually has.
        assert!(
            brief.contains("ne déclare aucun outil de publication"),
            "{name}: {brief}"
        );
        assert!(
            !brief.contains("jamais la room parente directement"),
            "{name}: {brief}"
        );
        // The old text tied principal relay to human decisions only ("si une décision
        // humaine doit atteindre la room parente"), falsely implying notable non-decision
        // milestones (progress/blocker/result) have no relay path at all.
        assert!(
            !brief.contains("si une décision humaine doit atteindre la room parente"),
            "{name}: relay must not be restricted to human decisions only: {brief}"
        );
        assert!(
            brief.contains("pas seulement pour une décision humaine"),
            "{name}: must ask for relay of notable facts, not just human decisions: {brief}"
        );
        assert!(
            brief.contains("avancement") && brief.contains("résultat"),
            "{name}: must name progress/result as relayable notable facts: {brief}"
        );
    }
}

#[test]
fn prelocalized_http_worker_brief_forbids_exploration_and_names_exact_target() {
    let scope = TaskWorkerScope::PrelocalizedEdit {
        path: "backend/src/lib.rs".into(),
        start_line: 40,
        end_line: 44,
    };
    let brief = worker_brief_markdown(
        "KT-435",
        "Sous-tâche Ollama prélocalisée",
        "Modifier uniquement la cible fournie",
        &[],
        "/wt/kt435",
        "kronn/task/KT-435",
        "abc1234",
        false,
        true,
        Some(&scope),
    );
    for needle in [
        "Cible mécanique prélocalisée",
        "`backend/src/lib.rs`",
        "`40..=44`",
        "un seul `read_file` contraint",
        "retire définitivement les outils de lecture",
        "Ne cherche pas ailleurs",
    ] {
        assert!(
            brief.contains(needle),
            "brief must mention `{needle}`\n{brief}"
        );
    }
    assert!(!brief.contains("Premier appel : `search_text`"), "{brief}");
    assert!(!brief.contains("## Workspace"), "{brief}");
    assert!(!brief.contains("## Décisions & périmètre"), "{brief}");
    assert!(
        brief.len() < 2_500,
        "specialized brief is too large: {}",
        brief.len()
    );
}

#[test]
fn http_turn_usage_sums_rework_and_exposes_peak_and_phase_breakdown() {
    let event =
        |id: &str, dispatch: &str, turns: serde_json::Value| crate::models::TaskExecutionEvent {
            id: id.into(),
            task_execution_id: "exec-1".into(),
            action: "http_turn_telemetry".into(),
            from_status: None,
            to_status: None,
            actor_kind: crate::models::PlanningActorKind::Backend,
            actor_id: Some("http-agent-runner".into()),
            actor_session_id: Some(dispatch.into()),
            changes: serde_json::json!({"version": 1, "turns": turns}),
            source_message_id: None,
            created_at: chrono::Utc::now(),
        };
    let turn = |number: u32, provider: &str, phase: &str, prompt: u64, eval: u64, duration: u64| {
        serde_json::json!({
            "turn": number,
            "provider": provider,
            "phase": phase,
            "prompt_tokens": prompt,
            "eval_tokens": eval,
            "duration_ms": duration,
            "provider_ok": true,
            "requested_tools": [],
            "executed_tools": []
        })
    };
    let events = vec![
        event(
            "e1",
            "dispatch-1",
            serde_json::json!([
                turn(1, "ollama", "read", 100, 10, 1_000),
                turn(2, "ollama", "mutation", 200, 20, 2_000)
            ]),
        ),
        event(
            "e2",
            "dispatch-2",
            serde_json::json!([turn(1, "nvidia", "delivery", 300, 30, 3_000)]),
        ),
    ];

    let usage = summarize_http_turn_usage(&events).unwrap();
    assert_eq!(usage.turns, 3);
    assert_eq!(usage.prompt_tokens, 600);
    assert_eq!(usage.eval_tokens, 60);
    assert_eq!(usage.traffic_tokens, 660);
    assert_eq!(usage.peak_context_tokens, 300);
    assert_eq!(usage.duration_ms, 6_000);
    assert_eq!(usage.phases.len(), 3);
    assert_eq!(
        usage.recent_turns[0].dispatch_id.as_deref(),
        Some("dispatch-1")
    );
    assert_eq!(
        usage.recent_turns[2].dispatch_id.as_deref(),
        Some("dispatch-2")
    );
    assert_eq!(
        (usage.cached_prompt_tokens, usage.cache_reported_turns),
        (0, 0),
        "legacy turns read as not reported"
    );
    assert_eq!(
        (
            usage.cache_write_prompt_tokens,
            usage.cache_write_reported_turns
        ),
        (0, 0),
        "legacy turns report no cache write"
    );
}

#[test]
fn http_turn_usage_sums_cached_prompt_tokens_next_to_legacy_turns() {
    let events = vec![crate::models::TaskExecutionEvent {
        id: "e1".into(),
        task_execution_id: "exec-1".into(),
        action: "http_turn_telemetry".into(),
        from_status: None,
        to_status: None,
        actor_kind: crate::models::PlanningActorKind::Backend,
        actor_id: Some("http-agent-runner".into()),
        actor_session_id: Some("dispatch-1".into()),
        changes: serde_json::json!({"version": 1, "turns": [
            {"turn": 1, "provider": "litellm", "phase": "exploration",
             "prompt_tokens": 1_000, "cached_prompt_tokens": 800, "eval_tokens": 10,
             "duration_ms": 1, "provider_ok": true, "requested_tools": [], "executed_tools": []},
            {"turn": 2, "provider": "litellm", "phase": "exploration",
             "prompt_tokens": 1_200, "eval_tokens": 10,
             "duration_ms": 1, "provider_ok": true, "requested_tools": [], "executed_tools": []}
        ]}),
        source_message_id: None,
        created_at: chrono::Utc::now(),
    }];
    let usage = summarize_http_turn_usage(&events).unwrap();
    assert_eq!(
        (usage.prompt_tokens, usage.cached_prompt_tokens),
        (2_200, 800)
    );
    assert_eq!(
        usage.cache_reported_turns, 1,
        "the unreported turn is not counted as uncached"
    );
    assert_eq!(
        (
            usage.phases[0].cached_prompt_tokens,
            usage.phases[0].cache_reported_turns
        ),
        (800, 1)
    );
    assert_eq!(usage.recent_turns[1].cached_prompt_tokens, None);
}

#[test]
fn http_turn_usage_sums_cache_writes_apart_from_cache_reads() {
    let events = vec![crate::models::TaskExecutionEvent {
        id: "e1".into(),
        task_execution_id: "exec-1".into(),
        action: "http_turn_telemetry".into(),
        from_status: None,
        to_status: None,
        actor_kind: crate::models::PlanningActorKind::Backend,
        actor_id: Some("http-agent-runner".into()),
        actor_session_id: Some("dispatch-1".into()),
        changes: serde_json::json!({"version": 1, "turns": [
            {"turn": 1, "provider": "litellm", "phase": "exploration",
             "prompt_tokens": 1_300, "cached_prompt_tokens": 0,
             "cache_write_prompt_tokens": 1_100, "eval_tokens": 10,
             "duration_ms": 1, "provider_ok": true, "requested_tools": [], "executed_tools": []},
            {"turn": 2, "provider": "litellm", "phase": "exploration",
             "prompt_tokens": 1_500, "cached_prompt_tokens": 1_100,
             "cache_write_prompt_tokens": 350, "eval_tokens": 10,
             "duration_ms": 1, "provider_ok": true, "requested_tools": [], "executed_tools": []},
            {"turn": 3, "provider": "litellm", "phase": "answer",
             "prompt_tokens": 900, "cached_prompt_tokens": 700, "eval_tokens": 10,
             "duration_ms": 1, "provider_ok": true, "requested_tools": [], "executed_tools": []}
        ]}),
        source_message_id: None,
        created_at: chrono::Utc::now(),
    }];
    let usage = summarize_http_turn_usage(&events).unwrap();
    assert_eq!(
        (usage.cached_prompt_tokens, usage.cache_reported_turns),
        (1_800, 3)
    );
    assert_eq!(
        (
            usage.cache_write_prompt_tokens,
            usage.cache_write_reported_turns
        ),
        (1_450, 2),
        "a turn without the field is not counted as writing nothing"
    );
    let exploration = &usage.phases[0];
    assert_eq!(
        (
            exploration.cache_write_prompt_tokens,
            exploration.cache_write_reported_turns
        ),
        (1_450, 2)
    );
    assert_eq!(
        (
            usage.phases[1].cache_write_prompt_tokens,
            usage.phases[1].cache_write_reported_turns
        ),
        (0, 0)
    );
    assert_eq!(usage.recent_turns[0].cache_write_prompt_tokens, Some(1_100));
    assert_eq!(usage.recent_turns[2].cache_write_prompt_tokens, None);
}

// ── HTTP mapping (KT-328 tranche 2, commit 3) — pure, no AppState needed. ──

#[test]
fn accept_outcome_fuses_unknown_and_wrong_acceptor_and_keeps_others_distinct() {
    // Anti-oracle: an unknown offer and a wrong caller MUST be indistinguishable, so
    // a non-target session cannot enumerate live offer ids or probe target identity.
    let unknown = accept_outcome_to_response(AcceptAttachOutcome::NotFound);
    let wrong = accept_outcome_to_response(AcceptAttachOutcome::WrongAcceptor);
    assert!(!unknown.success && !wrong.success);
    assert_eq!(unknown.error_code.as_deref(), Some("not_found"));
    assert_eq!(wrong.error_code.as_deref(), Some("not_found"));
    assert_eq!(
        unknown.error, wrong.error,
        "the two refusals must be byte-identical (no oracle)"
    );
    assert_eq!(
        unknown.error.as_deref(),
        Some("offer not found or not addressed to this session")
    );

    // Legitimate, actionable outcomes stay distinct + informative (each only reachable
    // AFTER caller == target, so naming the real state is not an oracle).
    let busy = accept_outcome_to_response(AcceptAttachOutcome::NotAcceptable {
        status: crate::models::WorkerOfferStatus::Accepted,
    });
    assert_eq!(busy.error_code.as_deref(), Some("conflict"));
    assert!(busy
        .error
        .as_deref()
        .unwrap()
        .contains(crate::models::WorkerOfferStatus::Accepted.as_str()));

    let binding = accept_outcome_to_response(AcceptAttachOutcome::BindingMismatch);
    assert_eq!(binding.error_code.as_deref(), Some("conflict"));
    let binding_error = binding.error.as_deref().unwrap();
    assert!(binding_error.contains("durably bound"));
    assert!(binding_error.contains("retry"));
    assert!(!binding_error.contains("discussion"));

    let expired = accept_outcome_to_response(AcceptAttachOutcome::Expired);
    assert_eq!(expired.error_code.as_deref(), Some("conflict"));
    assert!(expired.error.as_deref().unwrap().contains("expired"));

    let refused =
        accept_outcome_to_response(AcceptAttachOutcome::CheckpointRefused("task raced".into()));
    assert_eq!(refused.error_code.as_deref(), Some("conflict"));
    assert!(refused.error.as_deref().unwrap().contains("resumable"));
}

#[test]
fn provision_error_maps_to_stable_codes() {
    assert_eq!(
        provision_error_to_response(ProvisionError::TaskNotFound)
            .error_code
            .as_deref(),
        Some("not_found")
    );
    assert_eq!(
        provision_error_to_response(ProvisionError::NotLaunchable("nope".into()))
            .error_code
            .as_deref(),
        Some("validation")
    );
    let failed = provision_error_to_response(ProvisionError::WorkspaceFailed {
        reason: "disk full".into(),
        compensated: true,
    });
    assert_eq!(failed.error_code.as_deref(), Some("conflict"));
    assert!(failed
        .error
        .as_deref()
        .unwrap()
        .contains("compensated=true"));
    assert_eq!(
        provision_error_to_response(ProvisionError::Internal("boom".into()))
            .error_code
            .as_deref(),
        Some("internal")
    );
}

pub fn git(repo: &Path, args: &[&str]) -> std::process::Output {
    Command::new("git")
        .args(args)
        .current_dir(repo)
        .output()
        .unwrap()
}

pub fn init_repo() -> tempfile::TempDir {
    let dir = tempfile::Builder::new()
        .prefix("kronn-t3-")
        .tempdir()
        .unwrap();
    git(dir.path(), &["init", "-b", "main"]);
    git(dir.path(), &["config", "user.email", "t@t.com"]);
    git(dir.path(), &["config", "user.name", "T"]);
    std::fs::write(dir.path().join("README.md"), "# t").unwrap();
    git(dir.path(), &["add", "."]);
    git(dir.path(), &["commit", "-m", "init"]);
    dir
}

pub fn git_rev(repo: &Path, rev: &str) -> String {
    let out = git(repo, &["rev-parse", rev]);
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

