/// KT-1433: a validation that never reached the worker's code is the
/// host's to fix, never a reason to send the delivery back.
#[test]
fn a_validation_blocked_by_its_environment_is_not_the_workers_to_fix() {
    use crate::models::ValidationsAccess::{Docker, Sandbox};
    let denied = failure(
            Some(2),
            "permission denied while trying to connect to the docker API at unix:///Users/me/.orbstack/run/docker.sock",
        );
    let cause = environment_cause(Sandbox, None, &denied).expect("the sandbox closed Docker");
    assert!(cause.docker_elevation, "{}", cause.fix);

    let down = failure(
            Some(2),
            "failed to connect to the docker API at unix:///Users/me/.orbstack/run/docker.sock; check if the path is correct and if the daemon is running: dial unix ... connect: no such file or directory",
        );
    let cause = environment_cause(Sandbox, None, &down).expect("Docker is down");
    assert!(
        !cause.docker_elevation,
        "starting Docker is the fix, not an elevation"
    );
    assert!(cause.fix.contains("Démarre"), "{}", cause.fix);

    let missing: Result<std::path::PathBuf, String> = Err("no Docker socket found".into());
    let cause = environment_cause(Docker, Some(&missing), &denied).expect("no socket");
    assert!(!cause.docker_elevation);
    assert!(
        cause.fix.contains("no Docker socket found"),
        "{}",
        cause.fix
    );

    let refused = failure(None, "refused: this host has no sandbox Kronn can run");
    assert!(environment_cause(Sandbox, None, &refused).is_some());

    // Romu's real outputs: `make` prefixes the Docker CLI's refusal.
    let real = failure(
            Some(2),
            "Failed permission denied while trying to connect to the docker API at unix:///Users/priol/.orbstack/run/docker.sock\nmake: *** [iso-deps] Error 1",
        );
    assert!(
        environment_cause(Sandbox, None, &real)
            .unwrap()
            .docker_elevation
    );
    let opened: Result<std::path::PathBuf, String> =
        Ok("/Users/me/.orbstack/run/docker.sock".into());
    let cause = environment_cause(Docker, Some(&opened), &denied).unwrap();
    assert!(cause.fix.contains("a refusé la connexion"), "{}", cause.fix);

    for red in [
            // A test that quotes Docker's refusal, then fails on an assertion.
            failure(
                Some(1),
                "permission denied while trying to connect to the docker API at unix:///x/docker.sock\nexpected the error above\nAssertionError: wrong message\n1 tests failed",
            ),
            // Docker's refusal early in a long log, then the real failure.
            failure(
                Some(2),
                "permission denied while trying to connect to the docker API at unix:///x/docker.sock\nretrying with the local php\nstep 1\nstep 2\nstep 3\nstep 4\nstep 5\nstep 6\nsyntax error, unexpected token",
            ),
            failure(Some(1), "FAILED tests/Unit/MediaObjectImageLinkTest.php"),
            failure(Some(101), "error[E0308]: mismatched types"),
            failure(None, "timed out after 600s"),
        ] {
            assert!(
                environment_cause(Sandbox, None, &red).is_none(),
                "a real red validation stays the worker's: {}",
                red.output
            );
        }
}

/// KT-1753 — a validation that never reached the project's code because the
/// lane's environment stopped it (a missing tool, the sandbox, no network, a
/// compose service that is down) is the host's to fix, whatever the project
/// builds with; one that ran and failed stays the worker's.
#[test]
fn a_validation_stopped_by_the_lane_environment_is_not_the_workers_to_fix() {
    use crate::models::ValidationsAccess::Sandbox;
    let host = |code, output: &str, needle: &str| {
        let cause = environment_cause(Sandbox, None, &failure(code, output))
            .unwrap_or_else(|| panic!("`{output}` is the environment's"));
        assert!(!cause.docker_elevation, "{}", cause.fix);
        assert!(cause.fix.contains(needle), "{}", cause.fix);
    };
    // Exit 127: the tool is not installed or not on the lane's PATH.
    host(Some(127), "sh: composer: command not found", "127");
    // GNU make never exits 127: a tool missing behind a recipe makes it print
    // `Error 127` and exit 2.
    host(
        Some(2),
        "make: pnpm: No such file or directory\nmake: *** [Makefile:4: test] Error 127",
        "127",
    );
    host(
        Some(2),
        "/bin/sh: composer: command not found\nmake: *** [test] Error 127",
        "127",
    );
    // Any runner that says the command is not found, with no test result.
    host(Some(1), "bash: line 1: phpunit: command not found", "127");
    host(Some(1), "/bin/sh: 1: yarn: not found", "127");
    // The OS sandbox refused an operation.
    host(
        Some(1),
        "Error: EPERM: operation not permitted, mkdir '/Users/me/.cache/tool'",
        "bac à sable",
    );
    // No network in the lane.
    host(
        Some(6),
        "curl: (6) Could not resolve host: registry.example.com",
        "réseau",
    );
    host(
            Some(1),
            "npm ERR! request to https://registry.npmjs.org/x failed, reason: getaddrinfo EAI_AGAIN registry.npmjs.org",
            "réseau",
        );
    host(
            Some(101),
            "error: failed to get `serde` as a dependency\nCaused by: failed to lookup address information: nodename nor servname provided, or not known",
            "réseau",
        );
    // A compose service the validation `exec`s into is not up.
    host(Some(1), "service \"php\" is not running", "compose");
    host(Some(1), "no such service: php", "compose");

    for red in [
            // The tool ran, the test failed — even if the log quotes an environment error.
            failure(
                Some(1),
                "getaddrinfo EAI_AGAIN example.test\nAssertionError: expected the retry\n1 tests failed",
            ),
            failure(
                Some(127),
                "test result: FAILED. 1 passed; 1 failed\nfailures:\n  cmd::missing",
            ),
            failure(Some(1), "FAIL src/a.test.ts\nexpected 1 to be 2"),
            failure(Some(1), "error: operation not permitted was the expected message\nAssertionError"),
            failure(Some(101), "error[E0308]: mismatched types"),
            failure(Some(2), "make: *** [test] Error 1"),
            // `Error 127` as the prefix of another number is not the missing-tool code.
            failure(Some(2), "make: *** [test] Error 1270"),
            // A test log that quotes the message and then reports a failed test
            // (vitest / jest, PHPUnit).
            failure(
                Some(2),
                "bash: x: command not found\nFAIL src/a.test.ts\nexpected 1 to be 2\nmake: *** [test] Error 1",
            ),
            failure(
                Some(2),
                "sh: tool: command not found\nFAILURES!\nTests: 3, Assertions: 4, Failures: 1.\nmake: *** [test] Error 1",
            ),
        ] {
            assert!(
                environment_cause(Sandbox, None, &red).is_none(),
                "a real red validation stays the worker's: {}",
                red.output
            );
        }
}

/// KT-1753 review — a red run of pytest, mocha, jest or PHPUnit is the
/// worker's even when a failing test's own line says `Not Found`,
/// `Operation not permitted` or `Read-only file system`; only a shell's own
/// not-found report (or exit 127) means a missing tool.
#[test]
fn a_red_test_run_of_any_runner_never_reads_as_the_environment() {
    use crate::models::ValidationsAccess::Sandbox;
    for red in [
            // pytest: the per-test line, then the summary.
            failure(
                Some(1),
                "FAILED tests/test_api.py::test_get - requests.exceptions.HTTPError: 404 Client Error: Not Found for url: http://x/api\n=== 1 failed in 0.12s ===",
            ),
            failure(
                Some(1),
                "FAILED tests/test_io.py::test_write - PermissionError: [Errno 1] Operation not permitted: '/x'\n========== 1 failed, 3 passed in 0.40s ==========",
            ),
            failure(
                Some(1),
                "ERROR tests/test_io.py::test_tmp - OSError: [Errno 30] Read-only file system: '/x'\n=== 1 error in 0.10s ===",
            ),
            // mocha: `N failing`, then the failure with the server's answer.
            failure(
                Some(1),
                "  3 passing (20ms)\n  1 failing\n\n  1) api\n       GET /x:\n     Error: expected 200 \"OK\", got 404 \"Not Found\"",
            ),
            // jest's summary line.
            failure(
                Some(1),
                "Error: user: not found\nTests:       1 failed, 4 passed, 5 total",
            ),
            // PHPUnit's summary for errors (not only failures).
            failure(
                Some(2),
                "1) App\\Tests\\FileTest::testWrite\nfile_put_contents(/x): Failed to open stream: Read-only file system\n\nERRORS!\nTests: 3, Assertions: 2, Errors: 1.",
            ),
            // An application message that merely ends in `: not found`.
            failure(Some(1), "lookup failed: route /x: not found"),
            // Python unittest / Django: `Ran N test(s)`, then `FAILED (…)`.
            failure(
                Some(1),
                "ERROR: test_write (app.tests.FileTest)\nPermissionError: [Errno 1] Operation not permitted: '/x'\n----------------------------------------------------------------------\nRan 1 test in 0.001s\n\nFAILED (errors=1)",
            ),
            failure(
                Some(1),
                "OSError: [Errno 30] Read-only file system: '/x'\nRan 12 tests in 0.300s\n\nFAILED (failures=1, errors=2)",
            ),
            failure(
                Some(1),
                "socket.gaierror: [Errno 8] nodename nor servname provided, or not known\nTemporary failure in name resolution\nRan 3 tests in 0.020s\nFAILED (errors=1)",
            ),
        ] {
            assert!(
                environment_cause(Sandbox, None, &red).is_none(),
                "a real red test run stays the worker's: {}",
                red.output
            );
        }
    // The shells' own shapes still mean a missing tool.
    for missing in [
        "zsh: command not found: pnpm",
        "/bin/sh: 1: yarn: not found",
        "sh: phpunit: not found",
        "bash: line 1: composer: command not found",
        "env: 'node': No such file or directory",
    ] {
        let cause = environment_cause(Sandbox, None, &failure(Some(1), missing))
            .unwrap_or_else(|| panic!("`{missing}` is a missing tool"));
        assert!(cause.fix.contains("127"), "{}", cause.fix);
    }
}

/// The launch of a directory no test registered stays the plain one, and a
/// registered mechanism is the one the confinement is built from.
#[test]
fn validation_launch_follows_the_host_mechanism_of_the_tree() {
    let tree = tempfile::tempdir().unwrap();
    assert!(matches!(
        validation_launch(tree.path()),
        Ok(ValidationLaunch::Unconfined)
    ));

    test_validation_mechanisms()
        .lock()
        .unwrap()
        .insert(tree.path().to_path_buf(), None);
    assert!(validation_launch(tree.path()).is_err());

    test_validation_mechanisms().lock().unwrap().insert(
        tree.path().to_path_buf(),
        Some(crate::core::task_worker_sandbox::Mechanism::Seatbelt),
    );
    let launch = validation_launch(tree.path()).unwrap();
    assert!(
        launch.confinement().is_some(),
        "a host with a mechanism confines the validation"
    );
}

/// The host's sandbox, when this process may apply it (never from inside
/// another sandbox: macOS refuses a nested Seatbelt).
fn host_sandbox_that_applies() -> Option<crate::core::task_worker_sandbox::Mechanism> {
    use crate::core::task_worker_sandbox::Mechanism;
    let mechanism = Mechanism::of_host()?;
    let mut command = crate::core::cmd::sync_cmd(
        match mechanism {
            Mechanism::Seatbelt => "/usr/bin/sandbox-exec",
            Mechanism::Bubblewrap => "bwrap",
        },
        crate::core::child_env::ChildRoute::Tool,
    );
    match mechanism {
        Mechanism::Seatbelt => command.args(["-p", "(version 1)(allow default)", "/usr/bin/true"]),
        Mechanism::Bubblewrap => command.args(["--ro-bind", "/", "/", "true"]),
    };
    let applies = command.output().is_ok_and(|output| output.status.success());
    if !applies {
        eprintln!("skipped: the OS sandbox cannot be applied from this process");
    }
    applies.then_some(mechanism)
}

/// KT-1268 — the validation of a worker's tree runs under the lane's
/// sandbox: its build script writes inside the lane, cannot write outside
/// it, cannot reach a loopback service.
#[tokio::test]
async fn validation_of_a_worker_tree_runs_under_the_lane_sandbox() {
    let Some(mechanism) = host_sandbox_that_applies() else {
        return;
    };
    let repo = tempfile::tempdir().unwrap().keep().canonicalize().unwrap();
    let worktree = repo
        .join(".kronn")
        .join("worktrees")
        .join("task-kt-1268-live");
    let outside_dir = tempfile::tempdir().unwrap();
    let outside = outside_dir.path().canonicalize().unwrap().join("escaped");
    let inside = worktree.join("inside");
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    listener.set_nonblocking(true).unwrap();
    let port = listener.local_addr().unwrap().port();
    crate_with_build_script(
        &worktree,
        &format!(
            "fn main() {{\n    std::fs::write({inside:?}, \"x\").unwrap();\n    \
                 let _ = std::net::TcpStream::connect(\"127.0.0.1:{port}\")\n        \
                 .map(|_| std::fs::write({outside:?}.to_string() + \".net\", \"x\"));\n    \
                 std::fs::write({outside:?}, \"x\").expect(\"write outside the lane\");\n}}\n"
        ),
    );
    test_validation_mechanisms()
        .lock()
        .unwrap()
        .insert(worktree.clone(), Some(mechanism));
    let spec = ValidationSpec {
        command: "cargo build --offline".into(),
        quick_exec_id: None,
        timeout_secs: Some(300),
    };

    let (code, _duration, summary) = run_one_validation(&spec, &worktree).await;

    let escaped = outside.exists();
    let connected = outside.with_extension("net").exists() || {
        let mut net = outside.clone().into_os_string();
        net.push(".net");
        std::path::PathBuf::from(net).exists()
    };
    let accepted = listener.accept().is_ok();
    let ran_inside = inside.exists();
    let _ = std::fs::remove_dir_all(&repo);

    assert_ne!(
        code,
        Some(0),
        "the escape must fail the validation: {summary}"
    );
    assert!(ran_inside, "the build script ran in its lane: {summary}");
    assert!(!escaped, "the build script wrote outside the lane");
    assert!(!connected && !accepted, "the build script reached loopback");
}

/// KT-1268 review — the launch a shipped build uses (`validation_launch` is
/// the registry-driven one under `cfg(test)`): on this host it is the
/// confinement when the OS applies a sandbox from here, a refusal that
/// names why otherwise, and never a launch with the backend's rights.
#[test]
fn the_shipped_validation_launch_is_confined_or_refused_never_unconfined() {
    let repo = tempfile::tempdir().unwrap();
    let worktree = repo
        .path()
        .canonicalize()
        .unwrap()
        .join(".kronn")
        .join("worktrees")
        .join("task-kt-1268-shipped");
    std::fs::create_dir_all(&worktree).unwrap();

    let launch = host_validation_launch(&worktree);

    match launch {
        Ok(ValidationLaunch::Unconfined) => {
            panic!("the shipped launch ran a worker's tree unconfined")
        }
        Ok(ValidationLaunch::Level(_)) => {
            panic!("the lane launch of a worker's tree is never the trust-level one")
        }
        Ok(ValidationLaunch::Confined(_)) => {
            assert!(
                host_sandbox_that_applies().is_some(),
                "confined on a host whose OS sandbox cannot be applied"
            );
        }
        Err(reason) => {
            assert!(
                host_sandbox_that_applies().is_none(),
                "refused on a host that applies its sandbox: {reason}"
            );
            assert!(reason.contains("never run unconfined"), "{reason}");
        }
    }
}

/// KT-1268 review — a timed-out metadata resolution takes the whole group
/// of the confined launch down, not only its leader: a grandchild of the
/// worker's `rustc` wrapper must not outlive the timeout.
#[cfg(unix)] // runs a POSIX shell script fixture; relies on POSIX process groups and signals
#[tokio::test]
async fn metadata_timeout_kills_the_grandchildren_of_a_group_leader() {
    use std::process::Stdio;

    let dir = tempfile::tempdir().unwrap();
    let ready = dir.path().join("grandchild-started");
    let script = format!("(touch {ready:?}; sleep 30) & sleep 30");
    let mut command = tokio::process::Command::new("sh");
    command
        .args(["-c", &script])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);
    // The launcher of a confined validation: a session, hence a group, of
    // its own.
    crate::core::task_worker_env::detach_from_terminal(command.as_std_mut());
    let mut child = command.spawn().unwrap();
    let leader = child.id().unwrap() as libc::pid_t;
    // The grandchild exists before the timeout is armed.
    for _ in 0..200 {
        if ready.exists() {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert!(ready.exists(), "the grandchild never started");
    let group_alive = || {
        // SAFETY: signal 0 only probes whether the group has a member.
        unsafe { libc::killpg(leader, 0) == 0 }
    };
    assert!(group_alive(), "the fixture's group is not running");

    let result =
        wait_for_metadata_output(&mut child, std::time::Duration::from_millis(200), true).await;

    assert!(result.unwrap_err().contains("timed out"));
    assert!(child.try_wait().unwrap().is_some(), "the leader is reaped");
    // The grandchild is reparented and reaped by init: give it a moment.
    for _ in 0..100 {
        if !group_alive() {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert!(
        !group_alive(),
        "a grandchild of the metadata process outlived the timeout"
    );
}

#[tokio::test]
async fn observability_is_bounded_correlated_and_redacted() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _project_id) = seed(&db, repo.path()).await;
    let exec = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("observability".into()),
        },
    )
    .await
    .unwrap();

    let exec_id = exec.id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "DELETE FROM task_execution_events WHERE task_execution_id = ?1",
            [&exec_id],
        )?;
        conn.execute(
            "UPDATE task_executions SET status = 'Failed', review_rounds = 2, \
                        attempt_no = 2, created_at = '2026-08-21T00:00:00Z', \
                        updated_at = '2026-08-21T00:00:10Z', \
                        finished_at = '2026-08-21T00:00:10Z' WHERE id = ?1",
            [&exec_id],
        )?;
        let transitions = [
            (
                "Pending",
                "Provisioning",
                "2026-08-21T00:00:01Z",
                serde_json::json!({}),
            ),
            (
                "Provisioning",
                "Blocked",
                "2026-08-21T00:00:02Z",
                serde_json::json!({
                    "code": "awaiting_worker_acceptance",
                    "reason": "super-secret-agent-prose"
                }),
            ),
            (
                "Blocked",
                "Provisioning",
                "2026-08-21T00:00:04Z",
                serde_json::json!({}),
            ),
            (
                "Provisioning",
                "Working",
                "2026-08-21T00:00:05Z",
                serde_json::json!({}),
            ),
            (
                "Working",
                "AwaitingReview",
                "2026-08-21T00:00:07Z",
                serde_json::json!({}),
            ),
            (
                "AwaitingReview",
                "Escalated",
                "2026-08-21T00:00:09Z",
                serde_json::json!({ "timeout_kind": "review" }),
            ),
            (
                "Escalated",
                "Failed",
                "2026-08-21T00:00:10Z",
                serde_json::json!({}),
            ),
        ];
        for (index, (from, to, at, changes)) in transitions.into_iter().enumerate() {
            conn.execute(
                "INSERT INTO task_execution_events \
                     (id, task_execution_id, action, from_status, to_status, actor_kind, \
                      changes_json, created_at) VALUES (?1, ?2, 'transition', ?3, ?4, \
                      'backend', ?5, ?6)",
                rusqlite::params![
                    format!("event-{index}"),
                    exec_id,
                    from,
                    to,
                    changes.to_string(),
                    at
                ],
            )?;
        }
        crate::db::orchestration::record_validation_run(
            conn,
            &exec_id,
            Some("candidate"),
            &ValidationSpec {
                command: "test".into(),
                quick_exec_id: None,
                timeout_secs: None,
            },
            Some(1),
            Some(50),
            Some("super-secret-validation-output"),
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let exec_id = exec.id.clone();
    let view = db
        .with_conn(move |conn| execution_observability(conn, &exec_id))
        .await
        .unwrap();
    assert_eq!(view.lineage.execution.id, exec.id);
    assert_eq!(view.metrics.usage.duration_ms, 10_000);
    assert_eq!(view.metrics.waiting_duration_ms, 6_000);
    assert_eq!(view.metrics.review_rounds, 2);
    assert_eq!(view.metrics.attempt_count, 3);
    assert_eq!(view.metrics.validation_failures, 1);
    assert_eq!(view.audit_events.len(), 7);
    assert_eq!(
        view.metrics
            .state_durations
            .iter()
            .find(|metric| metric.status == TaskExecutionStatus::Provisioning)
            .map(|metric| metric.duration_ms),
        Some(2_000)
    );
    assert!(view
        .metrics
        .blocking_reasons
        .iter()
        .any(|metric| { metric.code == "awaiting_worker_acceptance" && metric.count == 1 }));
    assert!(view
        .metrics
        .blocking_reasons
        .iter()
        .any(|metric| metric.code == "timeout_review" && metric.count == 1));

    let public_json = serde_json::to_string(&view).unwrap();
    assert!(!public_json.contains("super-secret-agent-prose"));
    assert!(!public_json.contains("super-secret-validation-output"));
    assert!(!public_json.contains("changes"));
}

/// The whole saga on a real repo: the child does work, the parent moves on, and
/// the integration has to reconcile the two without ever rewriting the parent.
#[tokio::test]
async fn integrates_an_approved_execution_by_fast_forward() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, project_id) = seed(&db, repo.path()).await;

    let exec = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref.clone(),
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("integ-1".into()),
        },
    )
    .await
    .expect("provision should succeed");

    // KT-321 will pin the target at launch; until then the engine is handed one.
    let rid = exec.orchestration_run_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET target_branch = 'main' WHERE id = ?1",
            rusqlite::params![rid],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    // The worker commits in its own worktree.
    let (child, branch) =
        worktree::task_worktree_layout(repo.path(), &task_ref, exec_short(&exec.id)).unwrap();
    std::fs::write(child.join("worker.txt"), "done").unwrap();
    for args in [vec!["add", "."], vec!["commit", "-m", "worker work"]] {
        std::process::Command::new("git")
            .args(&args)
            .current_dir(&child)
            .output()
            .unwrap();
    }
    let candidate_before = git_rev(&child, "HEAD");

    // Meanwhile the parent moves on, so this is a real reconciliation.
    std::fs::write(repo.path().join("parent.txt"), "moved").unwrap();
    for args in [vec!["add", "."], vec!["commit", "-m", "parent moves"]] {
        std::process::Command::new("git")
            .args(&args)
            .current_dir(repo.path())
            .output()
            .unwrap();
    }
    let parent_tip = git_rev(repo.path(), "HEAD");

    let eid = exec.id.clone();
    let delivered = candidate_before.clone();
    db.with_conn(move |conn| {
        crate::db::worker_deliveries::upsert_delivery(conn, &eid, 0, &delivered, "{}")?;
        for to in [
            TaskExecutionStatus::AwaitingReview,
            TaskExecutionStatus::Approved,
        ] {
            crate::db::orchestration::transition_execution(
                conn,
                &eid,
                to,
                &backend_actor(),
                serde_json::json!({}),
            )?;
        }
        Ok(())
    })
    .await
    .unwrap();

    let outcome = run_integration(&db, &exec.id)
        .await
        .expect("integration runs");
    let IntegrationOutcome::Integrated { sha } = outcome else {
        panic!("expected the integration to land, got {outcome:?}");
    };

    // The parent advanced onto the candidate, and only forward.
    assert_eq!(git_rev(repo.path(), "HEAD"), sha);
    assert_ne!(sha, parent_tip, "the parent must have moved");
    assert_ne!(
        sha, candidate_before,
        "the candidate absorbed the parent tip"
    );
    let contains = std::process::Command::new("git")
        .args(["merge-base", "--is-ancestor", &parent_tip, &sha])
        .current_dir(repo.path())
        .output()
        .unwrap();
    assert!(
        contains.status.success(),
        "the parent's own work must survive"
    );
    assert!(repo.path().join("parent.txt").exists());
    assert!(repo.path().join("worker.txt").exists());

    // The checkpoints describe what happened, and the backup ref points back.
    let eid = exec.id.clone();
    let (target, merge, integrated, backup) = db
        .with_conn(move |conn| {
            Ok(conn.query_row(
                "SELECT candidate_target_sha, candidate_merge_sha, integrated_sha, backup_ref \
                       FROM task_executions WHERE id = ?1",
                rusqlite::params![eid],
                |r| {
                    Ok((
                        r.get::<_, Option<String>>(0)?,
                        r.get::<_, Option<String>>(1)?,
                        r.get::<_, Option<String>>(2)?,
                        r.get::<_, Option<String>>(3)?,
                    ))
                },
            )?)
        })
        .await
        .unwrap();
    assert_eq!(target.as_deref(), Some(parent_tip.as_str()));
    assert_eq!(merge.as_deref(), Some(sha.as_str()));
    assert_eq!(integrated.as_deref(), Some(sha.as_str()));
    // KT-1519 — `main` is the default branch: the integration closes the task.
    let tid = task_ref.clone();
    let task = db
        .with_conn(move |conn| Ok(crate::db::planning::get_task(conn, &tid)?.expect("task")))
        .await
        .unwrap();
    assert_eq!(task.summary.status, crate::models::PlanningTaskStatus::Done);
    assert!(task.summary.awaiting_merge.is_none());
    let backup = backup.expect("a backup ref must have been armed");
    assert_eq!(
        worktree::resolve_commit(repo.path(), &backup).unwrap(),
        parent_tip
    );

    // The terminal checkpoint is cross-aggregate: execution + integrated SHA
    // and the plan task's Done status commit together.
    let (eid, tref) = (exec.id.clone(), task_ref.clone());
    let (terminal, task_status, retained_workspace, child_workspace) = db
        .with_conn(move |conn| {
            let terminal = crate::db::orchestration::get_task_execution(conn, &eid)?
                .expect("execution survives terminal cleanup");
            let task_status = crate::db::planning::get_task(conn, &tref)?
                .expect("task survives integration")
                .summary
                .status;
            let retained_workspace: (
                String,
                Option<String>,
                Option<String>,
                String,
                Option<String>,
            ) = conn.query_row(
                "SELECT state, workspace_path, canonical_path, branch, head_sha
                       FROM discussion_workspaces WHERE task_execution_id = ?1",
                [&eid],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                    ))
                },
            )?;
            let child_workspace: (Option<String>, Option<String>) = conn.query_row(
                "SELECT workspace_path, worktree_branch FROM discussions WHERE id = ?1",
                [terminal.sub_discussion_id.as_deref().unwrap()],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )?;
            Ok((terminal, task_status, retained_workspace, child_workspace))
        })
        .await
        .unwrap();
    assert_eq!(terminal.status, TaskExecutionStatus::Done);
    assert_eq!(terminal.integrated_sha.as_deref(), Some(sha.as_str()));
    assert!(
        terminal.workspace_id.is_some(),
        "workspace provenance survives cleanup"
    );
    assert_eq!(task_status, PlanningTaskStatus::Done);
    assert_eq!(
        retained_workspace,
        (
            "detached".to_string(),
            Some(child.to_string_lossy().to_string()),
            None,
            branch.clone(),
            Some(candidate_before.clone()),
        ),
        "managed ownership evidence survives physical cleanup without claiming the removed path"
    );
    assert_eq!(
        child_workspace,
        (None, None),
        "child no longer points at a removed checkout"
    );
    assert!(!child.exists(), "integrated child worktree was removed");
    assert!(
        worktree::resolve_commit(repo.path(), &branch).is_err(),
        "integrated task branch was removed with its worktree"
    );

    // Crash-window replay: model the terminal DB checkpoint having landed
    // while its managed checkout/intent still exists. A Done replay must
    // finish cleanup instead of returning early forever.
    let recreated =
        worktree::create_task_worktree(repo.path(), &task_ref, exec_short(&exec.id), &sha).unwrap();
    let eid = exec.id.clone();
    let child_id = exec.sub_discussion_id.clone().unwrap();
    let parent = exec.parent_discussion_id.clone();
    let task_id = exec.task_id.clone();
    let pid = project_id.clone();
    let path = recreated.path.clone();
    let branch_for_db = recreated.branch.clone();
    let integrated_for_db = sha.clone();
    db.with_conn(move |conn| {
        let tx = conn.unchecked_transaction()?;
        let ws = crate::db::discussion_workspaces::upsert_managed(
            &tx,
            &eid,
            &child_id,
            &parent,
            Some(&task_id),
            &pid,
            &path,
            &path,
            &branch_for_db,
            &integrated_for_db,
            &integrated_for_db,
        )?;
        crate::db::orchestration::set_execution_workspace(
            &tx,
            &eid,
            &ws.id,
            &integrated_for_db,
            &branch_for_db,
        )?;
        crate::db::discussions::update_discussion_workspace(&tx, &child_id, &path, &branch_for_db)?;
        tx.commit()?;
        Ok(())
    })
    .await
    .unwrap();
    let replay = run_integration(&db, &exec.id).await.unwrap();
    assert!(matches!(
        replay,
        IntegrationOutcome::NotIntegrable {
            status: TaskExecutionStatus::Done
        }
    ));
    assert!(!std::path::Path::new(&recreated.path).exists());
    let eid = exec.id.clone();
    let replayed_workspace = db
        .with_conn(move |conn| {
            crate::db::discussion_workspaces::get_managed_for_execution(conn, &eid)
        })
        .await
        .unwrap()
        .expect("Done replay keeps durable provenance");
    assert_eq!(replayed_workspace.state, "detached");
    assert_eq!(replayed_workspace.canonical_path, None);
}

async fn approved_execution_with_commit(
    db: &Database,
    repo: &Path,
    key: &str,
    file: &str,
    content: &str,
    validations: Vec<ValidationSpec>,
) -> (TaskExecution, String, std::path::PathBuf) {
    let (task_ref, parent_id, _project_id) = seed(db, repo).await;
    let execution = provision_single_task_execution(
        db,
        ProvisionInput {
            task_reference: task_ref.clone(),
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some(key.into()),
        },
    )
    .await
    .unwrap();
    let run_id = execution.orchestration_run_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET target_branch = 'main', validation_json = ?2 \
                 WHERE id = ?1",
            rusqlite::params![run_id, serde_json::to_string(&validations)?],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let (child, _) =
        worktree::task_worktree_layout(repo, &task_ref, exec_short(&execution.id)).unwrap();
    std::fs::write(child.join(file), content).unwrap();
    for args in [vec!["add", "."], vec!["commit", "-m", "worker work"]] {
        assert!(git(&child, &args).status.success());
    }
    let execution_id = execution.id.clone();
    db.with_conn(move |conn| {
        for to in [
            TaskExecutionStatus::AwaitingReview,
            TaskExecutionStatus::Approved,
        ] {
            crate::db::orchestration::transition_execution(
                conn,
                &execution_id,
                to,
                &backend_actor(),
                serde_json::json!({}),
            )?;
        }
        Ok(())
    })
    .await
    .unwrap();
    (execution, task_ref, child)
}

#[tokio::test]
async fn refused_integration_on_a_doubly_checked_out_target_is_held_and_announced() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (execution, _, _) = approved_execution_with_commit(
        &db,
        repo.path(),
        "target-with-two-worktrees",
        "worker.txt",
        "validated",
        vec![],
    )
    .await;
    assert!(git(repo.path(), &["branch", "feature-target", "main"])
        .status
        .success());
    let checkouts = tempfile::tempdir().unwrap();
    let first = checkouts.path().join("first");
    let second = checkouts.path().join("second");
    for checkout in [&first, &second] {
        assert!(git(
            repo.path(),
            &[
                "worktree",
                "add",
                "--force",
                checkout.to_str().unwrap(),
                "feature-target"
            ]
        )
        .status
        .success());
    }
    let run_id = execution.orchestration_run_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET target_branch = 'feature-target' WHERE id = ?1",
            [run_id],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    for _ in 0..2 {
        let outcome = run_integration(&db, &execution.id).await.unwrap();
        assert!(
            matches!(outcome, IntegrationOutcome::Refused { .. }),
            "got {outcome:?}"
        );
    }
    let held = exec_of(&db, &execution.id).await;
    assert_eq!(held.status, TaskExecutionStatus::Approved);
    assert_eq!(
        held.blocked_reason_code,
        Some(BlockedReasonCode::IntegrationTargetNotCheckedOut)
    );
    assert!(held
        .blocked_reason
        .as_deref()
        .is_some_and(|reason| reason.contains("feature-target")));
    let parent = execution.parent_discussion_id.clone();
    let posted: Vec<String> = db
        .with_conn(move |conn| {
            let mut stmt = conn.prepare(
                "SELECT content FROM messages WHERE discussion_id = ?1 \
                     AND id LIKE 'orch-integration-refused:%' ORDER BY rowid",
            )?;
            let rows = stmt
                .query_map([parent], |row| row.get::<_, String>(0))?
                .collect::<rusqlite::Result<Vec<_>>>()?;
            Ok(rows)
        })
        .await
        .unwrap();
    assert_eq!(posted.len(), 1, "a repeated refusal must not spam the room");
    assert!(
        posted[0].contains("Garde `feature-target` extraite dans un seul worktree"),
        "the notice must name the fix: {}",
        posted[0]
    );
    let run_id = execution.orchestration_run_id.clone();
    let attention = db
        .with_conn(move |conn| crate::db::orchestration::principal_attention(conn, &run_id))
        .await
        .unwrap();
    assert_eq!(
        attention.awaiting_human, 1,
        "the held approval needs attention"
    );

    // Once the branch is checked out exactly once, the same durable approval integrates.
    assert!(git(
        repo.path(),
        &["worktree", "remove", "--force", second.to_str().unwrap()]
    )
    .status
    .success());
    let outcome = run_integration(&db, &execution.id).await.unwrap();
    assert!(
        matches!(outcome, IntegrationOutcome::Integrated { .. }),
        "got {outcome:?}"
    );
    let done = exec_of(&db, &execution.id).await;
    assert_eq!(done.status, TaskExecutionStatus::Done);
    assert_eq!(done.blocked_reason_code, None);
    assert_eq!(done.blocked_reason, None);
}

/// KT-1748 — integrating into a Kronn-managed worktree a run is using right
/// now is refused (`integration_target_busy_worktree`, naming the run) and
/// leaves the checkout untouched; the next attempt, once the run is over,
/// advances the same worktree.
#[tokio::test]
async fn integration_into_a_worktree_a_run_is_using_waits_for_the_run_to_finish() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (execution, _, _) = approved_execution_with_commit(
        &db,
        repo.path(),
        "target-in-busy-worktree",
        "worker.txt",
        "validated",
        vec![],
    )
    .await;
    assert!(git(repo.path(), &["branch", "feature-target", "main"])
        .status
        .success());
    let checkouts = tempfile::tempdir().unwrap();
    let held = checkouts.path().join("held");
    assert!(git(
        repo.path(),
        &["worktree", "add", held.to_str().unwrap(), "feature-target"]
    )
    .status
    .success());
    let held_tip = String::from_utf8_lossy(&git(&held, &["rev-parse", "HEAD"]).stdout)
        .trim()
        .to_string();
    let registered = held.canonicalize().unwrap().to_string_lossy().to_string();
    let run_id = execution.orchestration_run_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET target_branch = 'feature-target' WHERE id = ?1",
            [run_id],
        )?;
        conn.execute(
            "INSERT INTO workflows (id, name, project_id, trigger_json, steps_json, \
                 actions_json, safety_json, workspace_config_json, concurrency_limit, \
                 enabled, created_at, updated_at) VALUES ('w-auto', 'autoCode', NULL, '{}', \
                 '[]', '[]', '{}', NULL, NULL, 1, 'now', 'now')",
            [],
        )?;
        conn.execute(
            "INSERT INTO workflow_runs (id, workflow_id, workspace_path, started_at, status) \
                 VALUES ('run-live', 'w-auto', ?1, 'now', 'Running')",
            [registered],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let outcome = run_integration(&db, &execution.id).await.unwrap();
    let IntegrationOutcome::Refused { reason } = outcome else {
        panic!("an active run holds the target: got {outcome:?}");
    };
    assert!(
        reason.starts_with("integration_target_busy_worktree: ") && reason.contains("run-live"),
        "the refusal names the run: {reason}"
    );
    let held_back = exec_of(&db, &execution.id).await;
    assert_eq!(held_back.status, TaskExecutionStatus::Blocked);
    assert_eq!(
        held_back.blocked_from_status,
        Some(TaskExecutionStatus::Applying)
    );
    assert_eq!(
        String::from_utf8_lossy(&git(&held, &["rev-parse", "HEAD"]).stdout).trim(),
        held_tip,
        "the busy checkout did not move"
    );

    // Still busy: a resume asks again, is refused again and stays parked.
    assert!(resume_blocked_apply(&db, &execution.id).await.is_err());
    assert_eq!(
        exec_of(&db, &execution.id).await.status,
        TaskExecutionStatus::Blocked
    );

    // The run finished: the same worktree is idle and the next attempt lands.
    db.with_conn(|conn| {
        conn.execute(
            "UPDATE workflow_runs SET status = 'Success' WHERE id = 'run-live'",
            [],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let outcome = resume_blocked_apply(&db, &execution.id).await.unwrap();
    assert!(
        matches!(outcome, IntegrationOutcome::Integrated { .. }),
        "got {outcome:?}"
    );
    assert_eq!(
        exec_of(&db, &execution.id).await.status,
        TaskExecutionStatus::Done
    );
    assert_ne!(
        String::from_utf8_lossy(&git(&held, &["rev-parse", "HEAD"]).stdout).trim(),
        held_tip,
        "the idle checkout advanced"
    );
}

/// A validation run by `python3` from outside the repository. Tests steer it
/// through files in `control` to interleave Git work with a running validation.
fn scripted_validation(control: &Path, lines: &[&str]) -> ValidationSpec {
    let script = control.join("validate.py");
    std::fs::write(&script, lines.join("\n")).unwrap();
    ValidationSpec {
        command: format!("python3 {}", script.display()),
        quick_exec_id: None,
        timeout_secs: Some(60),
    }
}

async fn wait_for_file(path: &Path) {
    for _ in 0..1500 {
        if path.exists() {
            return;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    panic!("{} never appeared", path.display());
}

