#[tokio::test]
async fn a_launch_into_a_foreign_worktree_is_refused_and_a_kronn_worktree_accepted() {
    let repo = init_repo();
    crate::core::worktree::ownership_seam::enforce_for(repo.path());
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _pid) = seed(&db, repo.path()).await;
    let outside = tempfile::tempdir().unwrap();
    git(repo.path(), &["branch", "foreign"]);
    git(repo.path(), &["branch", "integ"]);
    let foreign = outside.path().join("wt");
    git(
        repo.path(),
        &["worktree", "add", &foreign.to_string_lossy(), "foreign"],
    );
    let owned = repo.path().join(".kronn/worktrees/integration");
    std::fs::create_dir_all(owned.parent().unwrap()).unwrap();
    git(
        repo.path(),
        &["worktree", "add", &owned.to_string_lossy(), "integ"],
    );

    let error =
        provision_single_task_execution(&db, launch_input(&task_ref, &parent_id, Some("foreign")))
            .await
            .expect_err("a worktree Kronn does not own is never written to");
    assert!(matches!(
        error,
        ProvisionError::NotLaunchable(ref reason)
            if reason.starts_with("integration_target_foreign_worktree: ")
    ));
    assert_eq!(count(&db, "SELECT COUNT(*) FROM task_executions").await, 0);

    let execution =
        provision_single_task_execution(&db, launch_input(&task_ref, &parent_id, Some("integ")))
            .await
            .expect("a Kronn-owned worktree may hold the integration branch");

    // The status names the target and the worktree before any integration.
    let exec_id = execution.id.clone();
    let detail = db
        .with_conn(move |conn| execution_detail(conn, &exec_id))
        .await
        .unwrap();
    assert_eq!(detail.target_branch.as_deref(), Some("integ"));
    let target = detail.integration_target.clone().unwrap();
    assert_eq!(
        target.state,
        crate::models::IntegrationTargetState::KronnWorktree
    );
    assert!(target.worktree.as_deref().unwrap().ends_with("integration"));
    let compact = serde_json::to_value(compact_execution_status(&detail, None)).unwrap();
    assert_eq!(compact["target_branch"], "integ");
    assert_eq!(compact["integration_target_state"], "kronn_worktree");
    assert_eq!(compact["integration_worktree"], target.worktree.unwrap());
}

#[tokio::test]
async fn the_status_shows_a_target_no_worktree_holds_and_the_owners_checkout() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _pid) = seed(&db, repo.path()).await;
    git(repo.path(), &["branch", "integ"]);
    let execution =
        provision_single_task_execution(&db, launch_input(&task_ref, &parent_id, Some("integ")))
            .await
            .unwrap();

    let exec_id = execution.id.clone();
    let detail = db
        .with_conn(move |conn| execution_detail(conn, &exec_id))
        .await
        .unwrap();
    let target = detail.integration_target.clone().unwrap();
    assert_eq!(target.branch, "integ");
    assert_eq!(target.worktree, None);
    assert_eq!(
        target.state,
        crate::models::IntegrationTargetState::NotCheckedOut
    );
    let compact = serde_json::to_value(compact_execution_status(&detail, None)).unwrap();
    assert_eq!(compact["target_branch"], "integ");
    assert_eq!(compact["integration_target_state"], "not_checked_out");
    assert!(compact.get("integration_worktree").is_none());

    // A run that was pinned to the owner's checkout reads as such, before
    // the integration finds out.
    crate::core::worktree::ownership_seam::enforce_for(repo.path());
    let run_id = execution.orchestration_run_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET target_branch = 'main' WHERE id = ?1",
            [&run_id],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let exec_id = execution.id.clone();
    let detail = db
        .with_conn(move |conn| execution_detail(conn, &exec_id))
        .await
        .unwrap();
    let target = detail.integration_target.unwrap();
    assert_eq!(
        target.state,
        crate::models::IntegrationTargetState::OwnerCheckout
    );
    assert_eq!(
        std::path::Path::new(target.worktree.as_deref().unwrap())
            .canonicalize()
            .unwrap(),
        repo.path().canonicalize().unwrap()
    );
}

#[tokio::test]
async fn the_preflight_refuses_an_owners_checkout_and_warns_when_no_branch_is_declared() {
    let repo = init_repo();
    crate::core::worktree::ownership_seam::enforce_for(repo.path());
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _pid) = seed(&db, repo.path()).await;
    git(repo.path(), &["branch", "integ"]);
    let prepare = |base_rev: Option<&'static str>| {
        let task_ref = task_ref.clone();
        let parent_id = parent_id.clone();
        let db = &db;
        async move {
            db.with_conn(move |conn| {
                let mut preparation =
                    prepare_task_execution(conn, &task_ref, &parent_id, &native_worker())?;
                integration_target_preparation(conn, &mut preparation, base_rev)?;
                Ok(preparation)
            })
            .await
            .unwrap()
        }
    };

    let refused = prepare(Some("main")).await;
    assert!(!refused.launchable);
    assert!(refused
        .reasons
        .iter()
        .any(|reason| reason.code == "integration_target_owner_checkout"));

    // The seeded task is not linked to the room's plan, so `launchable` says
    // nothing here: what counts is whether the target is among the reasons.
    let target_reasons = |preparation: &crate::models::TaskExecutionPreparation| {
        preparation
            .reasons
            .iter()
            .filter(|reason| reason.code.starts_with("integration_target_"))
            .count()
    };

    let undeclared = prepare(None).await;
    assert_eq!(
        target_reasons(&undeclared),
        0,
        "base_rev is still given at launch: a warning, not a refusal"
    );
    assert!(undeclared
        .warnings
        .iter()
        .any(|warning| warning.code == "integration_target_undeclared"));

    let accepted = prepare(Some("integ")).await;
    assert_eq!(target_reasons(&accepted), 0, "{:?}", accepted.reasons);
    assert!(accepted.warnings.is_empty());

    // The room's declared branch is what an absent base_rev checks.
    declare_integration_branch(&db, &parent_id, "main").await;
    let declared = prepare(None).await;
    assert!(!declared.launchable);
    assert!(declared.warnings.is_empty());
    assert!(declared
        .reasons
        .iter()
        .any(|reason| reason.code == "integration_target_owner_checkout"));
}

#[tokio::test]
async fn distinct_tasks_get_distinct_sub_discussions() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_a, parent_id, project_id) = seed(&db, repo.path()).await;
    let pid = project_id.clone();
    let task_b = db
        .with_conn(move |conn| {
            Ok(create_todo_task(conn, &pid, "Autre tâche")
                .summary
                .reference)
        })
        .await
        .unwrap();

    let ea = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_a,
            parent_discussion_id: parent_id.clone(),
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("a".into()),
        },
    )
    .await
    .unwrap();
    let eb = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_b,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("b".into()),
        },
    )
    .await
    .unwrap();

    assert_ne!(ea.id, eb.id);
    assert_ne!(
        ea.sub_discussion_id, eb.sub_discussion_id,
        "each execution owns a fresh sub-discussion (1:1, ADR §1)"
    );
}

// ── KT-1246 — tests_executed, capability section, smoke-check record. ──

fn manifest_with_tests_executed(
    tests: serde_json::Value,
    tests_executed: Option<serde_json::Value>,
) -> String {
    let mut manifest = serde_json::json!({
        "version": "1", "task_ref": "KT-1246", "head_sha": "abcdef1234567",
        "files_touched": [], "tests": tests, "dod_status": [],
        "docs": [], "migrations": [], "risks": [], "limitations": [],
        "summary": "x"
    });
    if let Some(value) = tests_executed {
        manifest["tests_executed"] = value;
    }
    manifest.to_string()
}

#[test]
fn tests_executed_is_optional_for_legacy_and_joined_deliveries() {
    let manifest =
        parse_delivery_manifest(&manifest_with_tests_executed(serde_json::json!([]), None))
            .expect("a delivery without the field stays readable");
    assert_eq!(manifest.tests_executed, None);
    // A legacy row serializes without inventing the field.
    assert!(!serde_json::to_string(&manifest)
        .unwrap()
        .contains("tests_executed"));
}

#[test]
fn tests_executed_states_which_tests_ran() {
    let ran = parse_delivery_manifest(&manifest_with_tests_executed(
        serde_json::json!([{ "name": "unit", "status": "pass", "evidence": "exit 0" }]),
        Some(serde_json::json!({
            "executed": true,
            "which": ["cargo nextest run -p kronn core::task_worker_env"]
        })),
    ))
    .unwrap();
    let declared = ran.tests_executed.unwrap();
    assert!(declared.executed);
    assert_eq!(declared.which.len(), 1);

    let none = parse_delivery_manifest(&manifest_with_tests_executed(
        serde_json::json!([{ "name": "unit", "status": "skipped", "evidence": "no shell" }]),
        Some(serde_json::json!({ "executed": false, "which": [] })),
    ))
    .unwrap();
    assert!(!none.tests_executed.unwrap().executed);
}

#[test]
fn tests_executed_must_agree_with_the_reported_tests() {
    let refusal = |tests: serde_json::Value, declared: serde_json::Value| {
        parse_delivery_manifest(&manifest_with_tests_executed(tests, Some(declared)))
            .unwrap_err()
            .to_string()
    };
    let pass = serde_json::json!([{ "name": "unit", "status": "pass", "evidence": "exit 0" }]);
    let skipped =
        serde_json::json!([{ "name": "unit", "status": "skipped", "evidence": "no shell" }]);

    assert!(refusal(
        pass.clone(),
        serde_json::json!({ "executed": true, "which": [] })
    )
    .contains("ne nomme aucune commande"));
    assert!(refusal(
        skipped,
        serde_json::json!({ "executed": true, "which": ["cargo test"] })
    )
    .contains("aucun test n'est rapporté"));
    assert!(refusal(
        serde_json::json!([]),
        serde_json::json!({ "executed": false, "which": ["cargo test"] })
    )
    .contains("`which` n'est pas vide"));
    assert!(
        refusal(pass, serde_json::json!({ "executed": false, "which": [] }))
            .contains("des tests sont rapportés")
    );
}

#[test]
fn a_native_delivery_must_state_tests_executed() {
    let dod: Vec<PlanningDodItem> = Vec::new();
    let without = serde_json::json!({
        "tests": [], "dod_status": [], "docs": [], "migrations": [],
        "risks": [], "limitations": [], "summary": "x"
    })
    .to_string();
    let error = prepare_native_worker_manifest(&without, &dod).unwrap_err();
    assert!(error.contains("`tests_executed`"), "{error}");

    let with = serde_json::json!({
        "tests": [], "dod_status": [], "docs": [], "migrations": [],
        "risks": [], "limitations": [], "summary": "x",
        "tests_executed": { "executed": false, "which": [] }
    })
    .to_string();
    let prepared = prepare_native_worker_manifest(&with, &dod).expect("accepted");
    assert_eq!(prepared["tests_executed"]["executed"], false);
}

fn sample_toolchain() -> ToolchainCapabilities {
    ToolchainCapabilities {
        rust_tests: Capability {
            available: true,
            reason: "cargo nextest and the offline dependency cache work".into(),
        },
        frontend_tests: Capability {
            available: false,
            reason: "the main checkout has no frontend/node_modules".into(),
        },
        port_binding: Capability {
            available: true,
            reason: "loopback binding works".into(),
        },
    }
}

#[test]
fn the_brief_shows_the_capabilities_before_its_tests_section() {
    let plain = worker_brief_markdown(
        "KT-1246",
        "Workers can build",
        "Objectif",
        &[],
        "/wt/kt1246",
        "kronn/task/KT-1246",
        "abc1234",
        true,
        true,
        None,
    );
    assert!(!plain.contains("Capacités de test"), "{plain}");

    let brief = insert_toolchain_section(plain, &sample_toolchain(), RoomLang::Fr);
    let section = brief.find("## Capacités de test").expect("section present");
    let tests = brief.find("## Tests\n").expect("tests section kept");
    assert!(section < tests, "the capabilities come first");
    assert!(brief.contains("✅ disponible — cargo nextest"), "{brief}");
    assert!(
        brief.contains("❌ indisponible — the main checkout has no frontend/node_modules"),
        "{brief}"
    );
    assert!(brief.contains("`tests_executed`"));
    // Whatever the worker serves takes its lane ports, never the host Kronn's.
    assert!(brief.contains("`$KRONN_PORT`"), "{brief}");
    assert!(brief.contains("`$VITE_DEV_PORT`"), "{brief}");
    assert!(brief.contains("--configLoader native"), "{brief}");
    assert!(brief.contains("s'arrête avec ton tour"), "{brief}");
    assert!(brief.contains("jamais sur un port par défaut"), "{brief}");
}

/// KT-1753 — the capability section describes the project, not Kronn: a PHP
/// project is told nothing about `cargo nextest`, Vite or Kronn's own binary,
/// ports are named by the lane's variables and no default port is free, and a
/// project that does build with Cargo and Node keeps its lines.
#[test]
fn the_capability_section_names_only_the_toolchains_the_project_has() {
    let root = |kind, dir: &str| crate::core::project_toolchains::PackageRoot {
        kind,
        rel_dir: dir.into(),
        workspace: None,
    };
    use crate::core::project_toolchains::{NodeManager, ToolchainKind};
    let php = [root(ToolchainKind::Composer, "")];
    let full = [
        root(ToolchainKind::Cargo, ""),
        root(ToolchainKind::Node(NodeManager::Npm), "frontend"),
    ];

    for lang in [RoomLang::En, RoomLang::Fr] {
        let section = toolchain_brief_section_in(&sample_toolchain(), Some(&php), lang);
        for kronn_only in [
            "cargo nextest",
            "vitest",
            "Vite",
            "debug/kronn",
            "Kronn backend",
        ] {
            assert!(!section.contains(kronn_only), "{kronn_only}: {section}");
        }
        assert!(section.contains("`$KRONN_PORT`"), "{section}");
        assert!(
            section.contains("3140") && section.contains("8080"),
            "{section}"
        );
        assert!(section.contains("tests_executed"), "{section}");

        let both = toolchain_brief_section_in(&sample_toolchain(), Some(&full), lang);
        assert!(both.contains("cargo nextest"), "{both}");
        assert!(both.contains("vitest"), "{both}");
        assert!(both.contains("$VITE_DEV_PORT"), "{both}");
        assert!(both.contains("$CARGO_TARGET_DIR/debug"), "{both}");
    }
}

/// KT-1753 — a Codex worker cannot write the worktree's git directory, so a
/// brief that tells it to `git merge` the target sets it up to fail: it gets
/// no merge section, only the line saying the principal integrates the
/// target. Every other runtime keeps the section.
#[test]
fn a_codex_brief_has_no_merge_section() {
    for lang in [RoomLang::En, RoomLang::Fr] {
        let brief = worker_brief_markdown_in(
            lang,
            "KT-1",
            "T",
            "Objective",
            &[],
            "/wt",
            "b",
            "abc",
            true,
            true,
            None,
            true,
        );
        let heading = if lang == RoomLang::En {
            "## Integrate the target branch"
        } else {
            "## Intégrer la branche cible"
        };
        assert!(brief.contains(heading), "{brief}");

        let codex = brief_for_agent(brief.clone(), Some("Codex"), lang);
        assert_eq!(codex.matches(heading).count(), 1, "{codex}");
        assert!(!codex.contains("git merge"), "{codex}");
        assert!(!codex.contains("MERGE_HEAD"), "{codex}");
        assert!(brief.contains("MERGE_HEAD"), "the other runtimes keep it");
        assert!(
            codex.contains(if lang == RoomLang::En {
                "the principal integrates the target branch"
            } else {
                "le principal intègre la branche cible"
            }),
            "{codex}"
        );
        // The sections around it survive.
        assert!(codex.contains("## Tests"), "{codex}");
        assert!(codex.contains("## Workspace"), "{codex}");

        assert_eq!(
            brief_for_agent(brief.clone(), Some("ClaudeCode"), lang),
            brief
        );
        assert_eq!(brief_for_agent(brief.clone(), None, lang), brief);
    }
}

/// KT-1316 — every brief variant reads in the room's language: an English
/// room gets no French heading or sentence, a French room keeps its brief.
#[test]
fn the_worker_brief_follows_the_room_language() {
    let dod = vec![PlanningDodItem {
        id: "dod-1".into(),
        sentence: "It works".into(),
        completed: false,
        position: 0,
        evidence: None,
        verification: PlanningDodVerification::PostIntegration,
    }];
    let scopes = [
        None,
        Some(TaskWorkerScope::PrelocalizedEdit {
            path: "src/lib.rs".into(),
            start_line: 3,
            end_line: 9,
        }),
    ];
    let french = [
        "## Objectif",
        "## Méthode",
        "## Contraintes",
        "## Format de livraison",
        "## Commence maintenant",
        "Arbitrages humains",
    ];
    for (shell, native) in [(true, true), (true, false), (false, true), (false, false)] {
        for scope in &scopes {
            let brief = |lang| {
                worker_brief_markdown_in(
                    lang,
                    "KT-1316",
                    "Title",
                    "Objective text",
                    &dod,
                    "/wt",
                    "kronn/task/kt-1316",
                    "abc1234",
                    shell,
                    native,
                    scope.as_ref(),
                    true,
                )
            };
            let english = brief(RoomLang::En);
            let case = format!("shell={shell} native={native} scope={scope:?}");
            assert!(english.contains("## Definition of Done"), "{case}");
            assert!(english.contains("task_exec_deliver"), "{case}");
            assert!(english.contains("live check"), "{case}: {english}");
            // A shell-less worker with a mechanical scope gets the short
            // bounded protocol instead of the full brief.
            if !shell && scope.is_some() {
                assert!(english.contains("## Bounded protocol"), "{case}");
                assert!(brief(RoomLang::Fr).contains("## Protocole borné"), "{case}");
            } else {
                assert!(english.contains("## Workspace"), "{case}");
                assert!(english.contains("## Start now"), "{case}: {english}");
                assert!(english.contains("## Delivery format"), "{case}");
                let french_brief = brief(RoomLang::Fr);
                assert!(french_brief.contains("## Commence maintenant"), "{case}");
                assert!(!french_brief.contains("## Start now"), "{case}");
            }
            for word in french {
                assert!(!english.contains(word), "{case}: `{word}` in {english}");
            }
            for sentence in ["Tu ", "Ne ", "Appelle ", "ton ", " le worker "] {
                assert!(
                    !english.contains(sentence),
                    "{case}: `{sentence}` in {english}"
                );
            }
            assert!(brief(RoomLang::Fr).contains("## Objectif"), "{case}");
        }
    }
}

