#[tokio::test]
async fn native_worker_delivery_uses_child_room_and_exact_provider_identity() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let execution = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("native-delivery".into()),
        },
    )
    .await
    .unwrap();
    let child = execution.sub_discussion_id.clone().unwrap();
    let dispatch_job_id = execution.dispatch_job_id.clone().unwrap();
    let lookup_dispatch_job_id = dispatch_job_id.clone();
    let dispatch_trigger = {
        db.with_conn(move |conn| {
            Ok(
                crate::db::agent_dispatch::get(conn, &lookup_dispatch_job_id)?
                    .unwrap()
                    .trigger_message_id,
            )
        })
        .await
        .unwrap()
    };

    let manifest = projected_manifest_for_execution(&db, &execution.id).await;
    for (discussion, provider, source_message_id) in [
        (child.as_str(), AgentType::Ollama, dispatch_trigger.as_str()),
        (
            "foreign-child",
            AgentType::ClaudeCode,
            dispatch_trigger.as_str(),
        ),
        (
            child.as_str(),
            AgentType::ClaudeCode,
            "another-same-provider-run",
        ),
    ] {
        let outcome = deliver_native_worker_manifest(
            &db,
            &execution.id,
            NativeExecutionCaller {
                discussion_id: discussion,
                agent_type: &provider,
                source_message_id: Some(source_message_id),
                alias: "native worker",
                actor_session_id: Some("native-delivery-turn"),
            },
            &dispatch_job_id,
            &manifest,
        )
        .await
        .unwrap();
        assert!(matches!(outcome, DeliverOutcome::NotAddressed));
    }

    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&dispatch_trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &manifest,
    )
    .await
    .unwrap();
    assert!(matches!(outcome, DeliverOutcome::Delivered { .. }));

    let expected_head = git_rev(
        Path::new(&managed_worktree_path(&db, &execution.id).await),
        "HEAD",
    );
    let expected_dod_id = dod_id_for_execution(&db, &execution.id).await;
    assert_eq!(
        execution.worker_dod_ids.as_deref(),
        Some(&[expected_dod_id.clone()][..])
    );
    let execution_id = execution.id.clone();
    let detail = db
        .with_conn(move |conn| execution_detail(conn, &execution_id))
        .await
        .unwrap();
    let persisted = detail.attempts[0]
        .delivery
        .as_ref()
        .expect("normalized native delivery persisted");
    assert_eq!(persisted.version, DELIVERY_CONTRACT_VERSION);
    assert_eq!(persisted.task_ref, "KT-1");
    assert_eq!(persisted.head_sha, expected_head);
    assert!(persisted.files_touched.is_empty());
    assert_eq!(persisted.dod_status[0].dod_id, expected_dod_id);
}

#[tokio::test]
async fn native_worker_delivery_refuses_wrong_dod_count_without_mutating_state() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let execution = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("native-delivery-wrong-dod-count".into()),
        },
    )
    .await
    .unwrap();
    let child = execution.sub_discussion_id.clone().unwrap();
    let dispatch_job_id = execution.dispatch_job_id.clone().unwrap();
    let lookup_dispatch_job_id = dispatch_job_id.clone();
    let dispatch_trigger = {
        db.with_conn(move |conn| {
            Ok(
                crate::db::agent_dispatch::get(conn, &lookup_dispatch_job_id)?
                    .unwrap()
                    .trigger_message_id,
            )
        })
        .await
        .unwrap()
    };
    let projected = serde_json::json!({
        "tests": [],
        "dod_status": [],
        "docs": [],
        "migrations": [],
        "risks": [],
        "limitations": [],
        "summary": "missing the required ordered DoD assertion",
        "tests_executed": { "executed": false, "which": [] }
    })
    .to_string();
    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&dispatch_trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &projected,
    )
    .await
    .unwrap();
    assert!(matches!(
        outcome,
        DeliverOutcome::InvalidManifest(ref detail)
            if detail.contains("exactly 1 item(s)") && detail.contains("got 0")
    ));

    let mut forged_mechanics: serde_json::Value =
        serde_json::from_str(&projected_manifest_for_execution(&db, &execution.id).await).unwrap();
    forged_mechanics["head_sha"] = serde_json::json!("deadbeef");
    forged_mechanics["version"] = serde_json::json!("1");
    forged_mechanics["task_ref"] = serde_json::json!("KT-forged");
    forged_mechanics["files_touched"] = serde_json::json!([]);
    forged_mechanics["reviewer_note"] = serde_json::json!("approved by Kronn");
    forged_mechanics["dod_status"][0]["dod_id"] = serde_json::json!("copied-id");
    forged_mechanics["tests"][0]["reviewer_note"] = serde_json::json!("trusted");
    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&dispatch_trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &forged_mechanics.to_string(),
    )
    .await
    .unwrap();
    let DeliverOutcome::InvalidManifest(detail) = outcome else {
        panic!("forged mechanics must be refused")
    };
    for forbidden in [
        "`head_sha`",
        "`version`",
        "`task_ref`",
        "`files_touched`",
        "`dod_status[0].dod_id`",
        "`reviewer_note`",
        "`tests[0].reviewer_note`",
    ] {
        assert!(
            detail.contains(forbidden),
            "one refusal must report every forbidden field; missing {forbidden}: {detail}"
        );
    }

    let task_id = execution.task_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE planning_task_dod_items SET id = 'same-count-new-id' WHERE task_id = ?1",
            [&task_id],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let drifted = projected_manifest_for_execution(&db, &execution.id).await;
    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&dispatch_trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &drifted,
    )
    .await
    .unwrap();
    assert!(matches!(
        outcome,
        DeliverOutcome::InvalidManifest(ref detail)
            if detail.contains("Definition of Done changed since this execution was launched")
    ));

    let execution_id = execution.id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE task_executions SET worker_dod_ids_json = NULL WHERE id = ?1",
            [&execution_id],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let pre_migration = projected_manifest_for_execution(&db, &execution.id).await;
    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&dispatch_trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &pre_migration,
    )
    .await
    .unwrap();
    assert!(matches!(
        outcome,
        DeliverOutcome::InvalidManifest(ref detail)
            if detail.contains("no launch-time Definition of Done snapshot")
    ));
    let execution_id = execution.id.clone();
    let stored = db
        .with_conn(move |conn| crate::db::orchestration::get_task_execution(conn, &execution_id))
        .await
        .unwrap()
        .unwrap();
    assert_eq!(stored.status, TaskExecutionStatus::Working);
}

/// KT-1402 — add a DoD item to the task of `exec_id` through a normal
/// `task_update`, keeping the existing items (and their ids).
async fn add_dod_item_by_update(db: &Database, exec_id: &str, sentence: &str) {
    let sentence = sentence.to_string();
    edit_dod_by_update(db, exec_id, move |items| {
        items.push(CreatePlanningDodItem {
            id: None,
            sentence,
            completed: false,
            verification: None,
        });
    })
    .await;
}

/// KT-1402 — edit the DoD of the task of `exec_id` through a normal
/// `task_update` that starts from the current items (ids kept).
async fn edit_dod_by_update(
    db: &Database,
    exec_id: &str,
    edit: impl FnOnce(&mut Vec<CreatePlanningDodItem>) + Send + 'static,
) {
    let task_id = exec_of(db, exec_id).await.task_id;
    db.with_conn(move |conn| {
        let task = crate::db::planning::get_task(conn, &task_id)?.context("task")?;
        let mut items = task
            .definition_of_done
            .iter()
            .map(|item| CreatePlanningDodItem {
                id: Some(item.id.clone()),
                sentence: item.sentence.clone(),
                completed: item.completed,
                verification: None,
            })
            .collect::<Vec<_>>();
        edit(&mut items);
        crate::db::planning::update_task(
            conn,
            &task_id,
            &crate::models::UpdatePlanningTaskRequest {
                title: None,
                description: None,
                status: None,
                priority: None,
                parent_id: None,
                blocked_reason: None,
                rank: None,
                project_ids: None,
                tags: None,
                definition_of_done: Some(items),
                links: None,
                actor: test_actor(),
            },
        )
    })
    .await
    .unwrap();
}

async fn provision_native_for_dod_edit(
    db: &Database,
    repo: &Path,
    key: &str,
) -> (TaskExecution, String, String) {
    let (task_ref, parent_id, _) = seed(db, repo).await;
    let execution = provision_single_task_execution(
        db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some(key.into()),
        },
    )
    .await
    .unwrap();
    let dispatch_job_id = execution.dispatch_job_id.clone().unwrap();
    let lookup = dispatch_job_id.clone();
    let trigger = db
        .with_conn(move |conn| {
            Ok(crate::db::agent_dispatch::get(conn, &lookup)?
                .unwrap()
                .trigger_message_id)
        })
        .await
        .unwrap();
    (execution, dispatch_job_id, trigger)
}

async fn discussion_contents(db: &Database, discussion_id: &str) -> Vec<String> {
    let discussion_id = discussion_id.to_string();
    db.with_conn(move |conn| {
        Ok(
            crate::db::discussions::get_discussion(conn, &discussion_id)?
                .unwrap()
                .messages
                .into_iter()
                .map(|message| message.content)
                .collect::<Vec<_>>(),
        )
    })
    .await
    .unwrap()
}

#[tokio::test]
async fn editing_the_dod_of_a_live_execution_re_adopts_it_and_tells_the_worker() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (execution, dispatch_job_id, trigger) =
        provision_native_for_dod_edit(&db, repo.path(), "kt1402-adopt").await;
    let child = execution.sub_discussion_id.clone().unwrap();
    let launched = execution.worker_dod_ids.clone().unwrap();

    add_dod_item_by_update(&db, &execution.id, "the new requirement holds").await;

    let after = exec_of(&db, &execution.id).await;
    let adopted = after.worker_dod_ids.clone().unwrap();
    assert_eq!(adopted.len(), launched.len() + 1);
    assert_eq!(adopted[..launched.len()], launched[..]);
    assert_eq!(after.status, TaskExecutionStatus::Working, "never parked");

    // The worker is told, in its own discussion, with the new list.
    let notice = discussion_contents(&db, &child)
        .await
        .into_iter()
        .find(|content| content.contains("the new requirement holds"))
        .unwrap_or_default();
    assert!(notice.contains("Definition of Done"), "{notice}");
    assert!(
        notice.contains(&format!("exactly {}", adopted.len()))
            || notice.contains(&format!("exactement {}", adopted.len())),
        "{notice}"
    );

    // A delivery bound to the new DoD is not refused for the drift.
    let manifest = projected_manifest_for_execution(&db, &execution.id).await;
    let outcome = deliver_native_worker_manifest(
        &db,
        &execution.id,
        NativeExecutionCaller {
            discussion_id: &child,
            agent_type: &AgentType::ClaudeCode,
            source_message_id: Some(&trigger),
            alias: "Claude Code",
            actor_session_id: Some("native-delivery-turn"),
        },
        &dispatch_job_id,
        &manifest,
    )
    .await
    .unwrap();
    if let DeliverOutcome::InvalidManifest(detail) = outcome {
        assert!(
            !detail.contains("Definition of Done changed"),
            "the worker must not be refused for a DoD drift: {detail}"
        );
    }
}

