/// KT-790 DoD-1 — the delivery's review request addresses the CLI principal
/// that launched the execution, so that principal's wait wakes on it instead
/// of timing out with the turn withheld by routing.
#[tokio::test]
async fn a_delivery_wakes_the_principal_cli_wait() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_, parent_id, _, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 202, &parent_id, "principal-sess").await;
    // The launch, review, resume and reassign handlers all pin through this.
    pin_cli_principal(&db, &exec_id, "ClaudeCode", "principal-sess").await;

    let manifest = clean_manifest_for_execution(&db, &exec_id).await;
    let outcome = deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &manifest)
        .await
        .unwrap();
    assert!(matches!(outcome, DeliverOutcome::Delivered { .. }));

    let Json(response) = crate::api::disc_invite::wait_for_peer(
        State(kt790_state(&db)),
        Path(parent_id),
        axum::extract::Query(crate::api::disc_invite::WaitForPeerQuery {
            since_sort_order: Some(0),
            timeout_secs: Some(2),
            exclude_agent_type: Some("ClaudeCode".into()),
            session_id: Some("principal-sess".into()),
            conversation_id: None,
            ack_awareness_upto: None,
        }),
    )
    .await;
    let wake = response.data.expect("wait_for_peer must answer");
    assert!(!wake.timed_out, "the delivery must wake the principal");
    let review_request = format!("orch-review-request:{exec_id}:0");
    let delivered = wake
        .messages
        .iter()
        .find(|message| message.message_id == review_request)
        .expect("the review request is the wake");
    assert!(delivered.addressed_to_caller);
    assert!(!delivered.awareness);
    assert_eq!(
        delivered.targets,
        vec![MessageTarget::cli(AgentType::ClaudeCode, 202)]
    );
}

/// KT-790 DoD-2 — `wait_for` holds the status read until the first matching
/// state, returns at once when it already holds, and stays bounded.
#[tokio::test]
async fn task_exec_status_wait_for_returns_at_the_first_matching_transition() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_, parent_id, _, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 202, &parent_id, "principal-sess").await;
    let state = kt790_state(&db);

    let delivering = {
        let (db, exec_id) = (db.clone(), exec_id.clone());
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(700)).await;
            let manifest = clean_manifest_for_execution(&db, &exec_id).await;
            deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &manifest)
                .await
                .unwrap()
        })
    };
    let started = std::time::Instant::now();
    let Json(woken) = task_exec_status(
        State(state.clone()),
        Path(exec_id.clone()),
        None,
        Json(kt790_principal_status(
            vec![
                TaskExecutionStatus::AwaitingReview,
                TaskExecutionStatus::Done,
                TaskExecutionStatus::Blocked,
            ],
            Some(30),
        )),
    )
    .await;
    let elapsed = started.elapsed();
    assert!(matches!(
        delivering.await.unwrap(),
        DeliverOutcome::Delivered { .. }
    ));
    let body = woken.data.expect("status with wait_for must answer");
    assert_eq!(body["lineage"]["execution"]["status"], "AwaitingReview");
    assert_eq!(body["wait"]["matched"], true);
    assert_eq!(body["wait"]["timed_out"], false);
    assert!(
        body["wait"]["waited_ms"].as_u64().unwrap() >= 500,
        "it waited for the transition: {body}"
    );
    assert!(
        elapsed < std::time::Duration::from_secs(10),
        "it returned at the transition, not at the 30 s timeout"
    );

    let Json(immediate) = task_exec_status(
        State(state.clone()),
        Path(exec_id.clone()),
        None,
        Json(kt790_principal_status(
            vec![TaskExecutionStatus::AwaitingReview],
            Some(30),
        )),
    )
    .await;
    let body = immediate.data.unwrap();
    assert_eq!(body["wait"]["matched"], true);
    assert!(body["wait"]["waited_ms"].as_u64().unwrap() < 500);

    let Json(bounded) = task_exec_status(
        State(state.clone()),
        Path(exec_id.clone()),
        None,
        Json(kt790_principal_status(
            vec![TaskExecutionStatus::Done],
            Some(1),
        )),
    )
    .await;
    let body = bounded.data.unwrap();
    assert_eq!(body["wait"]["matched"], false);
    assert_eq!(body["wait"]["timed_out"], true);
    assert!(body["wait"]["waited_ms"].as_u64().unwrap() >= 1000);

    let Json(plain) = task_exec_status(
        State(state),
        Path(exec_id),
        None,
        Json(kt790_principal_status(Vec::new(), None)),
    )
    .await;
    assert!(
        plain.data.unwrap().get("wait").is_none(),
        "a plain read keeps its historical shape"
    );
}

async fn kt791_delivered_execution(
    db: &std::sync::Arc<Database>,
    repo: &Path,
) -> (String, String, String) {
    let (_, parent_id, child_id, exec_id) = attached_cli_worker(db, repo).await;
    seed_cli_session(db, 202, &parent_id, "principal-sess").await;
    let manifest = clean_manifest_for_execution(db, &exec_id).await;
    let outcome = deliver_worker_manifest(db, &exec_id, "ClaudeCode", "sess-a", &manifest)
        .await
        .unwrap();
    assert!(matches!(outcome, DeliverOutcome::Delivered { .. }));
    (parent_id, child_id, exec_id)
}

async fn kt791_status(
    state: &AppState,
    exec_id: &str,
    view: TaskExecStatusView,
) -> (serde_json::Value, usize) {
    let mut request = kt790_principal_status(Vec::new(), None);
    request.view = view;
    let Json(response) = task_exec_status(
        State(state.clone()),
        Path(exec_id.to_string()),
        None,
        Json(request),
    )
    .await;
    let body = response.data.expect("status must answer");
    // Measured the way the MCP bridge prints a tool result.
    let printed = serde_json::to_string_pretty(&body).unwrap().chars().count();
    (body, printed)
}

/// KT-791 DoD-1 — `view: compact` answers a delivered, validated execution
/// with its state, attempt, head, last error, validations and next action in
/// under 1 000 characters, and stays under it however long the evidence is.
#[tokio::test]
async fn compact_status_carries_the_decision_fields_in_under_a_thousand_chars() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_, _, exec_id) = kt791_delivered_execution(&db, repo.path()).await;
    let head_sha = {
        let id = exec_id.clone();
        db.with_conn(move |conn| {
            Ok(crate::db::worker_deliveries::get_delivery(conn, &id, 0)?
                .unwrap()
                .head_sha)
        })
        .await
        .unwrap()
    };
    {
        let id = exec_id.clone();
        db.with_conn(move |conn| {
            for (command, exit_code, duration_ms) in [
                ("cargo fmt --check", 0, 2_140),
                ("cargo clippy --all-targets -- -D warnings", 0, 96_310),
                ("cargo test --no-fail-fast", 101, 412_877),
            ] {
                crate::db::orchestration::record_validation_run(
                    conn,
                    &id,
                    Some("candidate-sha"),
                    &crate::models::ValidationSpec {
                        command: command.into(),
                        quick_exec_id: None,
                        timeout_secs: Some(900),
                    },
                    Some(exit_code),
                    Some(duration_ms),
                    Some(&"test output line\n".repeat(400)),
                )?;
            }
            conn.execute(
                "UPDATE task_executions SET candidate_merge_sha = 'candidate-sha' WHERE id = ?1",
                [&id],
            )?;
            Ok(())
        })
        .await
        .unwrap();
    }
    let state = kt790_state(&db);

    let (full, full_chars) = kt791_status(&state, &exec_id, TaskExecStatusView::Full).await;
    assert!(
        full.get("lineage").is_some(),
        "full stays the default shape"
    );
    let (compact, compact_chars) =
        kt791_status(&state, &exec_id, TaskExecStatusView::Compact).await;
    assert!(
        compact_chars < 1000,
        "compact view is {compact_chars} chars: {compact:#}"
    );
    assert!(
        full_chars > 5 * compact_chars,
        "full {full_chars} vs compact {compact_chars}"
    );
    assert_eq!(compact["id"], exec_id);
    assert_eq!(compact["status"], "AwaitingReview");
    assert_eq!(compact["attempt"], 0);
    assert_eq!(compact["head_sha"], head_sha);
    assert_eq!(compact["next_action"]["tool"], "task_exec_review");
    let validations = compact["validations"].as_array().unwrap();
    assert_eq!(validations.len(), 3);
    assert_eq!(validations[2]["command"], "cargo test --no-fail-fast");
    assert_eq!(validations[2]["exit_code"], 101);
    assert_eq!(validations[2]["duration_ms"], 412_877);
    assert!(compact.get("lineage").is_none());

    // A pathological hold: a huge reason and many long quoted commands.
    {
        let id = exec_id.clone();
        db.with_conn(move |conn| {
            for index in 0..12 {
                crate::db::orchestration::record_validation_run(
                    conn,
                    &id,
                    Some("candidate-sha"),
                    &crate::models::ValidationSpec {
                        command: format!("run \"{}\" {index}", "\\\"x\\\"".repeat(60)),
                        quick_exec_id: None,
                        timeout_secs: None,
                    },
                    Some(1),
                    Some(10),
                    None,
                )?;
            }
            conn.execute(
                "UPDATE task_executions SET blocked_reason = ?2 WHERE id = ?1",
                rusqlite::params![&id, "« refusé » \"quoted\"\n".repeat(300)],
            )?;
            Ok(())
        })
        .await
        .unwrap();
    }
    let (worst, worst_chars) = kt791_status(&state, &exec_id, TaskExecStatusView::Compact).await;
    assert!(
        worst_chars < 1000,
        "worst case is {worst_chars} chars: {worst:#}"
    );
    assert_eq!(worst["status"], "AwaitingReview");
    assert!(worst["last_error"].as_str().unwrap().ends_with('…'));
    assert!(!worst["validations"].as_array().unwrap().is_empty());
}

/// KT-911 DoD-3 — `task_exec_status` lists the CLI sessions of the worker,
/// attempts included, with what each cost; the compact view names the latest
/// and still fits its budget.
#[tokio::test]
async fn task_exec_status_lists_the_workers_cli_sessions_attempts_included() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_, child_id, exec_id) = kt791_delivered_execution(&db, repo.path()).await;
    let state = kt790_state(&db);

    let (before, _) = kt791_status(&state, &exec_id, TaskExecStatusView::Full).await;
    assert_eq!(
        before["worker_sessions"],
        serde_json::json!([]),
        "a worker that ran no CLI session lists none"
    );
    let (compact, _) = kt791_status(&state, &exec_id, TaskExecStatusView::Compact).await;
    assert!(compact.get("worker_sessions").is_none());

    // The joined worker of this harness has no dispatch: give the execution
    // two real ones, the launch and the rework's.
    let dispatch = "dispatch-launch".to_string();
    {
        let (id, child_id, dispatch) = (exec_id.clone(), child_id.clone(), dispatch.clone());
        db.with_conn(move |conn| {
            for (n, job) in [dispatch.as_str(), "dispatch-rework"]
                .into_iter()
                .enumerate()
            {
                conn.execute(
                    "INSERT INTO messages (id, discussion_id, role, content, timestamp, \
                             sort_order) VALUES (?1, ?2, 'User', 'go', '2026-09-29T00:00:00Z', ?3)",
                    rusqlite::params![format!("m-{job}"), child_id, 9_000 + n as i64],
                )?;
                conn.execute(
                    "INSERT INTO agent_dispatch_jobs (id, discussion_id, trigger_message_id, \
                             trigger_sort_order, dedupe_key, chain_prompt_ids_json, status, \
                             available_at, created_at, updated_at) \
                         VALUES (?1, ?2, ?3, ?4, ?1, '[]', ?5, '2026-09-29T00:00:00Z', \
                             '2026-09-29T00:00:00Z', '2026-09-29T00:00:00Z')",
                    // One running dispatch per room: the launch is over.
                    rusqlite::params![
                        job,
                        child_id,
                        format!("m-{job}"),
                        9_000 + n as i64,
                        if n == 0 { "Completed" } else { "Running" }
                    ],
                )?;
            }
            crate::db::orchestration::attach_execution_dispatch(conn, &id, &dispatch)?;
            Ok(())
        })
        .await
        .unwrap();
    }
    {
        let (id, dispatch) = (exec_id.clone(), dispatch.clone());
        db.with_conn(move |conn| {
            let usd = |usd| crate::db::orchestration::WorkerSessionCost {
                usd,
                unknown_reason: usd
                    .is_none()
                    .then(|| "cache reads were not reported".into()),
            };
            // The first launch, a relaunch of the same dispatch, then a rework.
            crate::db::orchestration::record_worker_cli_session(
                conn,
                &id,
                &dispatch,
                "ClaudeCode",
                "11111111-1111-4111-8111-111111111111",
                Some(&usd(Some(0.42))),
            )?;
            crate::db::orchestration::record_worker_cli_session(
                conn,
                &id,
                &dispatch,
                "ClaudeCode",
                "22222222-2222-4222-8222-222222222222",
                Some(&usd(None)),
            )?;
            conn.execute(
                "UPDATE task_executions SET attempt_no = attempt_no + 1, \
                            dispatch_job_id = 'dispatch-rework' WHERE id = ?1",
                [&id],
            )?;
            crate::db::orchestration::record_worker_cli_session(
                conn,
                &id,
                "dispatch-rework",
                "ClaudeCode",
                "33333333-3333-4333-8333-333333333333",
                None,
            )?;
            Ok(())
        })
        .await
        .unwrap();
    }

    let (full, _) = kt791_status(&state, &exec_id, TaskExecStatusView::Full).await;
    let sessions = full["worker_sessions"].as_array().unwrap();
    assert_eq!(sessions.len(), 3, "{full:#}");
    assert_eq!(
        sessions[0]["session_id"],
        "11111111-1111-4111-8111-111111111111"
    );
    assert_eq!(sessions[0]["attempt_no"], 0);
    assert_eq!(sessions[0]["dispatch_job_id"], dispatch.as_str());
    assert_eq!(sessions[0]["agent_type"], "ClaudeCode");
    assert_eq!(sessions[0]["cost_usd"], 0.42);
    assert!(sessions[0].get("cost_unknown_reason").is_none());
    assert_eq!(
        sessions[1]["session_id"],
        "22222222-2222-4222-8222-222222222222"
    );
    assert!(sessions[1]["cost_usd"].is_null());
    assert_eq!(
        sessions[1]["cost_unknown_reason"],
        "cache reads were not reported"
    );
    assert_eq!(
        sessions[2]["attempt_no"], 1,
        "the rework is its own attempt"
    );
    assert_eq!(sessions[2]["dispatch_job_id"], "dispatch-rework");

    let (compact, compact_chars) =
        kt791_status(&state, &exec_id, TaskExecStatusView::Compact).await;
    assert!(compact_chars < 1000, "{compact_chars}: {compact:#}");
    assert_eq!(
        compact["worker_sessions"],
        serde_json::json!([
            "22222222-2222-4222-8222-222222222222",
            "33333333-3333-4333-8333-333333333333"
        ]),
        "the latest sessions, newest last"
    );
}

/// KT-791 DoD-2 — reassigning an execution awaiting review rejects its
/// delivery, keeps the task and the attempt history, and starts a new
/// attempt on the requested native worker.
#[tokio::test]
async fn reassign_from_awaiting_review_starts_a_new_attempt_on_the_requested_worker() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_, child_id, exec_id) = kt791_delivered_execution(&db, repo.path()).await;
    let before = exec_of(&db, &exec_id).await;
    assert_eq!(before.status, TaskExecutionStatus::AwaitingReview);

    let Json(reassigned) = task_exec_reassign(
        State(kt790_state(&db)),
        Path(exec_id.clone()),
        Json(TaskExecReassignRequest {
            source_agent: "ClaudeCode".into(),
            source_session_id: "principal-sess".into(),
            worker: Some(MessageTarget::discussion_agent(AgentType::Ollama)),
            validations: None,
            extend_review_rounds: None,
            reason: "the delivery misread the DoD; try a native worker".into(),
            room_agent: None,
        }),
    )
    .await;
    assert!(reassigned.success, "{:?}", reassigned.error);

    let after = exec_of(&db, &exec_id).await;
    assert_eq!(after.status, TaskExecutionStatus::Working);
    assert_eq!(after.attempt_no, before.attempt_no + 1, "a new attempt");
    assert_eq!(after.task_id, before.task_id);
    assert_eq!(after.sub_discussion_id.as_deref(), Some(child_id.as_str()));
    assert_eq!(after.worker_agent_type.as_deref(), Some("Ollama"));
    assert_eq!(after.worker_cli_session_id, None);
    assert_eq!(after.review_rounds, before.review_rounds);

    let id = exec_id.clone();
    let (kept_delivery, rejection, handoff, principal) = db
        .with_conn(move |conn| {
            let kept = crate::db::worker_deliveries::get_delivery(conn, &id, 0)?.is_some();
            let rejection: String = conn.query_row(
                "SELECT changes_json FROM task_execution_events \
                     WHERE task_execution_id = ?1 AND from_status = 'AwaitingReview' \
                       AND to_status = 'ChangesRequested'",
                [&id],
                |row| row.get(0),
            )?;
            let handoff: String = conn.query_row(
                "SELECT content FROM messages WHERE id LIKE 'orch-reassign:' || ?1 || ':%'",
                [&id],
                |row| row.get(0),
            )?;
            let principal = crate::db::orchestration::principal_notice_target(
                conn,
                &id,
                AgentType::ClaudeCode,
            )?;
            Ok((kept, rejection, handoff, principal))
        })
        .await
        .unwrap();
    assert!(kept_delivery, "the rejected delivery stays in the history");
    assert!(
        rejection.contains("\"delivery\":\"rejected\""),
        "{rejection}"
    );
    assert!(handoff.contains("Livraison rejetée"), "{handoff}");
    assert_eq!(
        principal,
        MessageTarget::cli(AgentType::ClaudeCode, 202),
        "the reassigning CLI now receives the execution's notices"
    );
    assert_eq!(
        count(&db, "SELECT COUNT(*) FROM agent_dispatch_jobs").await,
        1,
        "exactly one dispatch for the replacement worker"
    );
}

/// KT-791 DoD-2, CLI target — the reassignment offers the next attempt to the
/// requested session, which accepts it and works on it.
#[tokio::test]
async fn reassign_from_awaiting_review_offers_the_new_attempt_to_the_requested_cli() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (parent_id, _, exec_id) = kt791_delivered_execution(&db, repo.path()).await;
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;
    {
        let parent_id = parent_id.clone();
        db.with_conn(move |conn| {
            crate::db::disc_source::bind_to_source(conn, &parent_id, "ClaudeCode", "sess-b")
        })
        .await
        .unwrap();
    }

    let Json(reassigned) = task_exec_reassign(
        State(kt790_state(&db)),
        Path(exec_id.clone()),
        Json(TaskExecReassignRequest {
            source_agent: "ClaudeCode".into(),
            source_session_id: "principal-sess".into(),
            worker: Some(MessageTarget::cli(AgentType::ClaudeCode, 102)),
            validations: None,
            extend_review_rounds: None,
            reason: "hand the rework to another CLI".into(),
            room_agent: None,
        }),
    )
    .await;
    assert!(reassigned.success, "{:?}", reassigned.error);

    let after = exec_of(&db, &exec_id).await;
    assert_eq!(after.attempt_no, 1);
    let offer = {
        let id = exec_id.clone();
        db.with_conn(move |conn| {
            crate::db::worker_offers::get_active_offer_for_attempt(conn, &id, 1)
        })
        .await
        .unwrap()
        .expect("the new attempt is offered to the requested session")
    };
    assert_eq!(offer.target_cli_session_id, 102);
    let offer_text = {
        let message_id = offer.offer_message_id.clone().unwrap();
        db.with_conn(move |conn| {
            conn.query_row(
                "SELECT content FROM messages WHERE id = ?1",
                [&message_id],
                |row| row.get::<_, String>(0),
            )
            .map_err(anyhow::Error::from)
        })
        .await
        .unwrap()
    };
    assert!(offer_text.contains("Livraison rejetée"), "{offer_text}");

    let accepted = accept_worker_offer_and_attach(&db, &offer.id, "ClaudeCode", "sess-b", "sess-b")
        .await
        .unwrap();
    assert!(matches!(accepted, AcceptAttachOutcome::Attached { .. }));
    let working = exec_of(&db, &exec_id).await;
    assert_eq!(working.status, TaskExecutionStatus::Working);
    assert_eq!(working.worker_cli_session_id, Some(102));
    assert_eq!(working.attempt_no, 1);
}

/// A session that is NOT the execution's worker cannot deliver — NotAddressed (fused
/// with unknown-execution → anti-oracle), and nothing moves (DoD-2).
#[tokio::test]
async fn deliver_is_refused_for_a_wrong_worker_session() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, parent_id, _child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;
    // A DIFFERENT active session (same provider) — not this execution's worker.
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;

    let outcome = deliver_worker_manifest(
        &db,
        &exec_id,
        "ClaudeCode",
        "sess-b",
        &manifest_json("abcdef1234567"),
    )
    .await
    .unwrap();
    assert!(
        matches!(outcome, DeliverOutcome::NotAddressed),
        "wrong worker → NotAddressed"
    );

    // Nothing moved: still Working, no delivery row, no review request.
    let e = exec_id.clone();
    let (status, delivery, review_msgs) = db
        .with_conn(move |conn| {
            let status = crate::db::orchestration::get_task_execution(conn, &e)?
                .unwrap()
                .status;
            let delivery = crate::db::worker_deliveries::get_delivery(conn, &e, 0)?;
            let n: i64 = conn.query_row(
                "SELECT COUNT(*) FROM messages WHERE id LIKE 'orch-review-request:%'",
                [],
                |r| r.get(0),
            )?;
            Ok((status, delivery, n))
        })
        .await
        .unwrap();
    assert_eq!(
        status,
        TaskExecutionStatus::Working,
        "execution stays Working"
    );
    assert!(
        delivery.is_none(),
        "no delivery persisted for a rejected caller"
    );
    assert_eq!(review_msgs, 0, "no review request posted");
}

/// A crash/double-click resubmit of the SAME attempt converges idempotently: still
/// Delivered, exactly one delivery row and one review request (DoD-8).
#[tokio::test]
async fn deliver_is_idempotent_on_resume() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, _parent_id, _child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;

    let manifest = clean_manifest_for_execution(&db, &exec_id).await;
    let first = deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &manifest)
        .await
        .unwrap();
    assert!(matches!(first, DeliverOutcome::Delivered { .. }));
    let again = deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &manifest)
        .await
        .unwrap();
    assert!(
        matches!(again, DeliverOutcome::Delivered { .. }),
        "a resubmit of the same attempt converges to Delivered, got {again:?}"
    );

    assert_eq!(
        count(&db, "SELECT COUNT(*) FROM task_execution_deliveries").await,
        1,
        "exactly one delivery row after a resubmit"
    );
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM messages WHERE id LIKE 'orch-review-request:%'"
        )
        .await,
        1,
        "exactly one review request after a resubmit"
    );
}

/// The worker cannot deliver an execution that is not `Working` — a parked (Blocked)
/// execution names the real state (NotDeliverable), reachable only after authz.
#[tokio::test]
async fn deliver_is_refused_when_the_execution_is_not_working() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    // Parked, NOT accepted → Blocked(awaiting_worker_acceptance), worker session = 101.
    let (_task_ref, _parent_id, _child_id, offer_id) = parked_cli_worker(&db, repo.path()).await;
    let exec_id = {
        let oid = offer_id.clone();
        db.with_conn(move |conn| {
            Ok(crate::db::worker_offers::get_worker_offer(conn, &oid)?
                .unwrap()
                .task_execution_id)
        })
        .await
        .unwrap()
    };

    let outcome = deliver_worker_manifest(
        &db,
        &exec_id,
        "ClaudeCode",
        "sess-a",
        &manifest_json("abcdef1234567"),
    )
    .await
    .unwrap();
    assert!(
        matches!(
            outcome,
            DeliverOutcome::NotDeliverable {
                status: TaskExecutionStatus::Blocked
            }
        ),
        "a Blocked execution is not deliverable, got {outcome:?}"
    );
}

/// A malformed manifest is refused (InvalidManifest naming the missing field) AFTER
/// authz — a real validation refusal, never a silent accept.
#[tokio::test]
async fn deliver_rejects_an_invalid_manifest() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, _parent_id, _child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;

    // head_sha dropped — DoD-1 requires it.
    let bad = serde_json::json!({
        "version": "1", "task_ref": "KT-319",
        "files_touched": [], "tests": [], "dod_status": [],
        "docs": [], "migrations": [], "risks": [], "limitations": [], "summary": "x"
    })
    .to_string();
    let outcome = deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &bad)
        .await
        .unwrap();
    match outcome {
        DeliverOutcome::InvalidManifest(detail) => {
            assert!(
                detail.contains("head_sha"),
                "must name the missing field, got: {detail}"
            );
        }
        other => panic!("expected InvalidManifest, got {other:?}"),
    }
    // Still Working, nothing persisted.
    let e = exec_id.clone();
    let status = db
        .with_conn(move |conn| {
            Ok(crate::db::orchestration::get_task_execution(conn, &e)?
                .unwrap()
                .status)
        })
        .await
        .unwrap();
    assert_eq!(status, TaskExecutionStatus::Working);
}

#[tokio::test]
async fn deliver_refuses_dirty_edits_then_accepts_the_same_change_once_committed() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, _parent_id, _child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    std::fs::write(Path::new(&path).join("delivery-proof.txt"), "durable\n").unwrap();
    let base_head = git_rev(Path::new(&path), "HEAD");
    let dirty_manifest = manifest_json_with_files_for_dod(
        &base_head,
        serde_json::json!([{ "path": "delivery-proof.txt", "kind": "added" }]),
        &dod_id,
        true,
    );

    let refused = deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &dirty_manifest)
        .await
        .unwrap();
    match refused {
        DeliverOutcome::InvalidManifest(detail) => assert!(
            detail.contains("uncommitted changes") && detail.contains("delivery-proof.txt"),
            "the refusal must tell the worker exactly what to commit: {detail}"
        ),
        other => panic!("dirty delivery must be refused, got {other:?}"),
    }
    assert_eq!(
        exec_of(&db, &exec_id).await.status,
        TaskExecutionStatus::Working,
        "a refused manifest must leave the worker able to commit and retry"
    );

    git(Path::new(&path), &["add", "delivery-proof.txt"]);
    git(Path::new(&path), &["commit", "-m", "add delivery proof"]);
    let committed_head = git_rev(Path::new(&path), "HEAD");
    let committed_manifest = manifest_json_with_files_for_dod(
        &committed_head,
        serde_json::json!([{ "path": "delivery-proof.txt", "kind": "added" }]),
        &dod_id,
        true,
    );
    let delivered =
        deliver_worker_manifest(&db, &exec_id, "ClaudeCode", "sess-a", &committed_manifest)
            .await
            .unwrap();
    assert!(matches!(delivered, DeliverOutcome::Delivered { .. }));
}

