    let path = managed_worktree_path(&db, &exec_id).await;
    let base = exec_of(&db, &exec_id).await.base_sha.unwrap();
    write_grafts(
        Path::new(&path),
        &git_rev(Path::new(&path), "HEAD"),
        &[&base],
    );
    let shown = git(
        Path::new(&path),
        &["log", "--format=%H", &format!("{base}..HEAD")],
    );
