/// KT-1291 — the carry rides the review checkpoint's transaction: when the
/// checkpoint fails after the guards passed, the item is still on the task,
/// no `dod_carried` event exists and no review row was persisted.
#[tokio::test]
async fn a_failed_review_checkpoint_detaches_no_carried_dod() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (exec_id, head, dod_id) = unmet_delivery(&db, repo.path()).await;
    let carrier = carrier_task(
        &db,
        &exec_id,
        PlanningTaskStatus::Todo,
        "Le module compile et les tests passent.",
    )
    .await;
    db.with_conn(|conn| {
        conn.execute_batch(
            "CREATE TRIGGER kt1291_checkpoint_fails
                 BEFORE UPDATE OF status ON task_executions
                 WHEN LOWER(NEW.status) = 'approved'
                 BEGIN SELECT RAISE(ABORT, 'checkpoint failed'); END;",
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let result = decide_review(
        &db,
        &exec_id,
        &approve_carrying(&head, &dod_id, &carrier),
        "ClaudeCode",
        "sess-b",
    )
    .await;
    assert!(
        result.is_err(),
        "the checkpoint must have failed: {result:?}"
    );

    assert_eq!(task_of(&db, &exec_id).await.definition_of_done.len(), 1);
    assert!(task_event_payloads(&db, &exec_id, "dod_carried")
        .await
        .is_empty());
    assert!(review_row(&db, &exec_id).await.is_none());
    assert_eq!(
        exec_of(&db, &exec_id).await.status,
        TaskExecutionStatus::AwaitingReview
    );
}

/// KT-1254 round 2 — a live check is the principal's call: the worker's own
/// session, an HTTP agent and an anonymous agent are refused when they set,
/// remove or tick it; a live check is never ticked without evidence nor
/// downgraded and ticked in one write; the principal and a human may.
#[tokio::test]
async fn only_the_principal_or_a_human_may_set_remove_or_tick_a_live_check() {
    use crate::models::{
        CreatePlanningDodItem, UpdatePlanningDodItemRequest, UpdatePlanningTaskRequest,
    };
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, parent_id, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;
    let task_id = exec_of(&db, &exec_id).await.task_id;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    let agent = |id: &str, session: Option<&str>| PlanningActor {
        kind: PlanningActorKind::Agent,
        id: Some(id.to_string()),
        session_id: session.map(str::to_string),
        source_message_id: None,
        token_declared: false,
    };
    let worker = agent("ClaudeCode", Some("sess-a"));
    let principal = agent("ClaudeCode", Some("sess-b"));
    let http_agent = agent("kronn-agent", Some("native:disc:msg"));
    let anonymous = agent("ClaudeCode", None);

    let db_ref = &db;
    let replace = |actor: PlanningActor, mode: Option<PlanningDodVerification>, completed: bool| {
        let (task_id, dod_id) = (task_id.clone(), dod_id.clone());
        async move {
            db_ref
                .with_conn(move |conn| {
                    crate::db::planning::update_task(
                        conn,
                        &task_id,
                        &UpdatePlanningTaskRequest {
                            title: None,
                            description: None,
                            status: None,
                            priority: None,
                            parent_id: None,
                            blocked_reason: None,
                            rank: None,
                            project_ids: None,
                            tags: None,
                            definition_of_done: Some(vec![CreatePlanningDodItem {
                                id: Some(dod_id),
                                sentence: "tests pass".into(),
                                completed,
                                verification: mode,
                            }]),
                            links: None,
                            actor,
                        },
                    )
                })
                .await
        }
    };
    let tick = |actor: PlanningActor, evidence: Option<&str>| {
        let (task_id, dod_id) = (task_id.clone(), dod_id.clone());
        let evidence = evidence.map(str::to_string);
        async move {
            db_ref
                .with_conn(move |conn| {
                    crate::db::planning::update_dod_item(
                        conn,
                        &task_id,
                        &dod_id,
                        &UpdatePlanningDodItemRequest {
                            completed: true,
                            evidence,
                            actor,
                        },
                    )
                })
                .await
        }
    };
    let mode_of = || {
        let task_id = task_id.clone();
        async move {
            let task = db_ref
                .with_conn(move |conn| crate::db::planning::get_task(conn, &task_id))
                .await
                .unwrap()
                .unwrap();
            task.definition_of_done[0].verification
        }
    };
    let live = Some(PlanningDodVerification::PostIntegration);

    // Setting: the worker, an HTTP agent and an anonymous agent are refused.
    for refused in [&worker, &http_agent, &anonymous] {
        assert!(
            replace(refused.clone(), live, false).await.is_err(),
            "{refused:?} must not declare a live check"
        );
    }
    assert_eq!(mode_of().await, PlanningDodVerification::Worker);
    replace(principal.clone(), live, false).await.unwrap();
    assert_eq!(mode_of().await, PlanningDodVerification::PostIntegration);

    // Removing — downgrading it, or dropping the item — is refused alike.
    let worker_mode = Some(PlanningDodVerification::Worker);
    for refused in [&worker, &http_agent, &anonymous] {
        assert!(replace(refused.clone(), worker_mode, false).await.is_err());
    }
    assert_eq!(mode_of().await, PlanningDodVerification::PostIntegration);

    // Never ticked without evidence, by an array replace or a bare tick.
    assert!(replace(principal.clone(), live, true).await.is_err());
    assert!(tick(principal.clone(), None).await.is_err());
    assert!(tick(PlanningActor::default(), Some("  ")).await.is_err());
    // A worker cannot tick the principal's check, evidence or not.
    assert!(tick(worker.clone(), Some("looks fine to me"))
        .await
        .is_err());
    assert!(tick(http_agent.clone(), Some("looks fine to me"))
        .await
        .is_err());

    // Downgrade + tick in ONE write is refused, even for the principal or a
    // human; nothing changed.
    assert!(replace(principal.clone(), worker_mode, true).await.is_err());
    assert!(replace(PlanningActor::default(), worker_mode, true)
        .await
        .is_err());
    assert_eq!(mode_of().await, PlanningDodVerification::PostIntegration);

    // The principal ticks with evidence.
    let ticked = tick(principal.clone(), Some("replayed live: ok"))
        .await
        .unwrap();
    assert!(ticked.definition_of_done[0].completed);
    assert_eq!(
        ticked.definition_of_done[0].evidence.as_deref(),
        Some("replayed live: ok")
    );
}

/// KT-1954 — the bridge names the agent on a planning write without the
/// session it joined with, so the principal was refused its own live check. The
/// DoD write proves the principal by the identity the execution tools send.
#[tokio::test]
async fn the_principal_ticks_a_live_check_by_the_identity_the_execution_tools_send() {
    use crate::models::UpdatePlanningDodItemRequest;
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, parent_id, child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;
    seed_cli_session(&db, 103, &child_id, "sess-other-room").await;
    let task_id = exec_of(&db, &exec_id).await.task_id;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    let live = dod_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE planning_task_dod_items SET verification = 'post_integration' WHERE id = ?1",
            [&live],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let db_ref = &db;
    let proven = |agent: &'static str, session: &'static str| {
        let task_id = task_id.clone();
        async move {
            db_ref
                .with_conn(move |conn| {
                    live_check_principal(conn, &task_id, agent, session, None, None)
                })
                .await
                .unwrap()
        }
    };
    assert_eq!(
        proven("ClaudeCode", "sess-b").await,
        Some(("ClaudeCode".to_string(), "sess-b".to_string()))
    );
    // The worker's own session, a session of the worker's room, another
    // provider's name on the session, an unknown session and no identity.
    for (agent, session) in [
        ("ClaudeCode", "sess-a"),
        ("ClaudeCode", "sess-other-room"),
        ("Codex", "sess-b"),
        ("ClaudeCode", "sess-nobody"),
        ("ClaudeCode", ""),
        ("", ""),
    ] {
        assert_eq!(proven(agent, session).await, None, "{agent}/{session}");
    }
    let unknown_task = db
        .with_conn(|conn| {
            live_check_principal(conn, "KT-999999", "ClaudeCode", "sess-b", None, None)
        })
        .await
        .unwrap();
    assert_eq!(unknown_task, None);

    // What the bridge really sends as the planning actor: the agent, no session.
    let request = |evidence: Option<&str>| UpdatePlanningDodItemRequest {
        completed: true,
        evidence: evidence.map(str::to_string),
        actor: PlanningActor {
            kind: PlanningActorKind::Agent,
            id: Some("ClaudeCode".to_string()),
            session_id: None,
            source_message_id: None,
            token_declared: false,
        },
    };
    let tick = |evidence: Option<&'static str>, principal_proven: bool| {
        let (task_id, dod_id, request) = (task_id.clone(), dod_id.clone(), request(evidence));
        async move {
            db_ref
                .with_conn(move |conn| {
                    crate::db::planning::update_dod_item_as(
                        conn,
                        &task_id,
                        &dod_id,
                        &request,
                        principal_proven,
                    )
                })
                .await
        }
    };
    // Unproven, it is refused as before; proven, the evidence is still owed.
    assert!(tick(Some("replayed live: ok"), false).await.is_err());
    assert!(tick(None, true).await.is_err());
    let ticked = tick(Some("replayed live: ok"), true).await.unwrap();
    assert!(ticked.definition_of_done[0].completed);
    assert_eq!(
        ticked.definition_of_done[0].evidence.as_deref(),
        Some("replayed live: ok")
    );
}

/// KT-1954 — through the route, the journal names the identity that was
/// proven, not the actor the body declared, and an unproven caller is refused.
#[tokio::test]
async fn a_proven_live_check_tick_is_journaled_under_the_proven_identity() {
    use crate::api::planning::{update_dod_item_as, UpdateDodItemBody};
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (_task_ref, parent_id, _child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;
    let task_id = exec_of(&db, &exec_id).await.task_id;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    let live = dod_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE planning_task_dod_items SET verification = 'post_integration' WHERE id = ?1",
            [&live],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let state = state_for(&db);
    let body = |session: &str| -> UpdateDodItemBody {
        serde_json::from_value(serde_json::json!({
            "completed": true,
            "evidence": "replayed live: ok",
            "actor": { "kind": "agent", "id": "someone-else", "session_id": "declared" },
            "source_agent": "ClaudeCode",
            "source_session_id": session,
        }))
        .unwrap()
    };
    let call = |session: &'static str| {
        update_dod_item_as(
            State(state.clone()),
            None,
            Path((task_id.clone(), dod_id.clone())),
            Json(body(session)),
        )
    };
    assert!(!call("sess-unknown").await.0.success);
    // A bridge token that names the principal's session as its actor, the
    // way the gate hands it over: the claim authorises nothing, with or
    // without the principal fields, unless the grant runs in the parent room.
    let token = |rooms: &[&str]| {
        Some(axum::Extension(crate::core::bridge_token::BridgeCaller {
            token_id: "tok".into(),
            project: None,
            own_discussions: rooms.iter().map(|room| room.to_string()).collect(),
            own_run: None,
            agent: None,
            room_agent_of: Vec::new(),
            own_execution: None,
            own_sessions: Vec::new(),
        }))
    };
    let forged = |principal_fields: bool| -> UpdateDodItemBody {
        let mut body = serde_json::json!({
            "completed": true,
            "evidence": "forged",
            "actor": { "kind": "agent", "id": "ClaudeCode", "session_id": "sess-b",
                       "token_declared": true },
        });
        if principal_fields {
            body["source_agent"] = "ClaudeCode".into();
            body["source_session_id"] = "sess-b".into();
        }
        serde_json::from_value(body).unwrap()
    };
    for (rooms, principal_fields) in [(vec!["d-stranger"], false), (vec!["d-stranger"], true)] {
        let answer = update_dod_item_as(
            State(state.clone()),
            token(&rooms),
            Path((task_id.clone(), dod_id.clone())),
            Json(forged(principal_fields)),
        )
        .await;
        assert!(!answer.0.success, "{rooms:?} {principal_fields}");
    }
    // The parent room's own launch, without the principal fields, is refused
    // too: the body's session alone is never the proof.
    let unproven = update_dod_item_as(
        State(state.clone()),
        token(&[parent_id.as_str()]),
        Path((task_id.clone(), dod_id.clone())),
        Json(forged(false)),
    )
    .await;
    assert!(!unproven.0.success);
    // The worker here is a CLI of the parent room (KT-837): a grant of that
    // room that never joined the principal's session may be the worker's.
    let co_member = update_dod_item_as(
        State(state.clone()),
        token(&[parent_id.as_str()]),
        Path((task_id.clone(), dod_id.clone())),
        Json(forged(true)),
    )
    .await;
    assert!(!co_member.0.success);
    let joined = token(&[parent_id.as_str()]).map(|axum::Extension(grant)| {
        axum::Extension(crate::core::bridge_token::BridgeCaller {
            own_sessions: vec![102],
            ..grant
        })
    });
    let proven = update_dod_item_as(
        State(state.clone()),
        joined,
        Path((task_id.clone(), dod_id.clone())),
        Json(forged(true)),
    )
    .await;
    assert!(proven.0.success);
    assert!(call("sess-b").await.0.success);
    let task = task_id.clone();
    let actor: (String, Option<String>) = db
        .with_conn(move |conn| {
            Ok(conn.query_row(
                "SELECT actor_id, actor_session_id FROM planning_task_events
                  WHERE task_id = ?1 ORDER BY created_at DESC, rowid DESC LIMIT 1",
                [&task],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )?)
        })
        .await
        .unwrap();
    assert_eq!(
        actor,
        ("ClaudeCode".to_string(), Some("sess-b".to_string()))
    );
}

/// KT-1954 — a DoD body without the principal fields is the body it always was.
#[test]
fn a_dod_body_reads_with_or_without_the_principal_identity() {
    use crate::api::planning::UpdateDodItemBody;
    let bare: UpdateDodItemBody =
        serde_json::from_value(serde_json::json!({ "completed": true })).unwrap();
    assert!(bare.request.completed && bare.source_session_id.is_empty());
    assert!(bare.room_agent.is_none());
    // A malformed identity does not fail the body.
    let malformed: UpdateDodItemBody =
        serde_json::from_value(serde_json::json!({ "completed": true, "room_agent": "x" }))
            .unwrap();
    assert!(malformed.request.completed);
    let named: UpdateDodItemBody = serde_json::from_value(serde_json::json!({
        "completed": true,
        "evidence": "seen",
        "actor": { "kind": "agent", "id": "Codex" },
        "source_agent": "Codex",
        "source_session_id": "adhoc-1",
    }))
    .unwrap();
    assert_eq!(named.request.evidence.as_deref(), Some("seen"));
    assert_eq!(named.source_session_id, "adhoc-1");
}

/// KT-1931 — once the execution is over the rule is unchanged: its room's
/// principal and a human still tick with evidence, a CLI of another room is
/// refused, and the refusal names who may.
#[tokio::test]
async fn a_live_check_is_still_ticked_by_the_same_actors_once_the_execution_is_over() {
    use crate::models::{
        CreatePlanningDodItem, UpdatePlanningDodItemRequest, UpdatePlanningTaskRequest,
    };
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, parent_id, child_id, exec_id) = attached_cli_worker(&db, repo.path()).await;
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;
    seed_cli_session(&db, 103, &child_id, "sess-other-room").await;
    let task_id = exec_of(&db, &exec_id).await.task_id;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    let agent = |session: &str| PlanningActor {
        kind: PlanningActorKind::Agent,
        id: Some("ClaudeCode".to_string()),
        session_id: Some(session.to_string()),
        source_message_id: None,
        token_declared: false,
    };
    let db_ref = &db;
    let set = |actor: PlanningActor, completed: bool, evidence: Option<&str>| {
        let (task_id, dod_id) = (task_id.clone(), dod_id.clone());
        let evidence = evidence.map(str::to_string);
        async move {
            db_ref
                .with_conn(move |conn| {
                    crate::db::planning::update_dod_item(
                        conn,
                        &task_id,
                        &dod_id,
                        &UpdatePlanningDodItemRequest {
                            completed,
                            evidence,
                            actor,
                        },
                    )
                })
                .await
        }
    };
    {
        let (task_id, dod_id, actor) = (task_id.clone(), dod_id.clone(), agent("sess-b"));
        db.with_conn(move |conn| {
            crate::db::planning::update_task(
                conn,
                &task_id,
                &UpdatePlanningTaskRequest {
                    title: None,
                    description: None,
                    status: None,
                    priority: None,
                    parent_id: None,
                    blocked_reason: None,
                    rank: None,
                    project_ids: None,
                    tags: None,
                    definition_of_done: Some(vec![CreatePlanningDodItem {
                        id: Some(dod_id),
                        sentence: "tests pass".into(),
                        completed: false,
                        verification: Some(PlanningDodVerification::PostIntegration),
                    }]),
                    links: None,
                    actor,
                },
            )
        })
        .await
        .unwrap();
    }
    force_status(&db, &exec_id, "Done").await;

    let refusal = set(agent("sess-other-room"), true, Some("seen live"))
        .await
        .unwrap_err()
        .to_string();
    assert!(
        refusal.contains("a human") && refusal.contains("principal of the task's execution"),
        "the refusal names who may tick: {refusal}"
    );
    assert!(set(agent("sess-b"), true, None).await.is_err());

    let ticked = set(agent("sess-b"), true, Some("replayed live: ok"))
        .await
        .unwrap();
    assert_eq!(
        ticked.definition_of_done[0].evidence.as_deref(),
        Some("replayed live: ok")
    );
    set(agent("sess-b"), false, None).await.unwrap();
    let by_human = set(PlanningActor::default(), true, Some("seen on my instance"))
        .await
        .unwrap();
    assert!(by_human.definition_of_done[0].completed);
    assert_eq!(
        by_human.definition_of_done[0].evidence.as_deref(),
        Some("seen on my instance")
    );
}

