/// KT-1262 — a DoD item added between approve and integration is neither
/// verified by the approve nor a live check: the integration is held BEFORE
/// the git apply, so the target does not move and no execution is parked
/// with its code already on it.
#[tokio::test]
async fn a_dod_item_added_after_the_approve_holds_the_integration_before_the_apply() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_parent, _child, exec_id, _head, path) = delivered_awaiting_review(&db, repo.path()).await;
    unticked_dod(&db, &exec_id).await;
    let dod_id = dod_id_for_execution(&db, &exec_id).await;
    let task_id = exec_of(&db, &exec_id).await.task_id;
    let target_before = git_rev(repo.path(), "main");

    let decision = approve_with_evidence(&git_rev(Path::new(&path), "HEAD"), &dod_id, "green");
    let reviewed = decide_review(&db, &exec_id, &decision, "ClaudeCode", "sess-b")
        .await
        .unwrap();
    // Between approve and integration someone adds an item.
    let added = {
        let task_id = task_id.clone();
        db.with_conn(move |conn| {
            conn.execute(
                "INSERT INTO planning_task_dod_items
                     (id, task_id, sentence, completed, position, created_at, updated_at)
                     VALUES ('added-late', ?1, 'a late requirement', 0, 1, ?2, ?2)",
                rusqlite::params![task_id, chrono::Utc::now().to_rfc3339()],
            )?;
            Ok(())
        })
        .await
    };
    added.unwrap();

    let refused = continue_approved_review(&db, reviewed).await;
    match refused {
        Err(ProvisionError::NotLaunchable(reason)) => {
            assert!(reason.contains("added-late"), "{reason}")
        }
        other => panic!("the late DoD item must hold the integration, got {other:?}"),
    }
    assert_eq!(
        git_rev(repo.path(), "main"),
        target_before,
        "the target must not have moved"
    );
    let execution = exec_of(&db, &exec_id).await;
    assert!(execution.integrated_sha.is_none());
    assert_ne!(execution.status, TaskExecutionStatus::Done);
    assert_ne!(execution.status, TaskExecutionStatus::Applying);
    let task = db
        .with_conn(move |conn| crate::db::planning::get_task(conn, &task_id))
        .await
        .unwrap()
        .unwrap();
    assert_ne!(task.summary.status, PlanningTaskStatus::Done);
}

/// Waits for `expected`, failing at once on a state it can no longer leave.
/// The ceiling only bounds a hang.
async fn wait_for_execution_status(
    db: &Database,
    exec_id: &str,
    expected: TaskExecutionStatus,
) -> TaskExecution {
    tokio::time::timeout(Duration::from_secs(60), async {
        loop {
            let execution = exec_of(db, exec_id).await;
            if execution.status == expected {
                return execution;
            }
            if execution.status.is_terminal()
                || matches!(
                    execution.status,
                    TaskExecutionStatus::Escalated | TaskExecutionStatus::Interrupted
                )
            {
                panic!(
                    "execution {exec_id} reached {} instead of {}: {:?} {:?}",
                    execution.status.as_str(),
                    expected.as_str(),
                    execution.blocked_reason_code,
                    execution.blocked_reason
                );
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("execution {exec_id} did not reach {}", expected.as_str()))
}

fn review_request(exec_id: &str, decision: &str) -> ReviewRequest {
    ReviewRequest {
        task_execution_id: exec_id.to_string(),
        decision: serde_json::from_str(decision).expect("review decision JSON"),
        source_agent: Some("ClaudeCode".to_string()),
        source_session_id: Some("sess-b".to_string()),
        room_agent: None,
    }
}

/// A validation that signals `started` and holds until `release` appears, so a
/// test acts while it is running instead of racing a fixed delay.
fn held_validation(control: &Path) -> ValidationSpec {
    let (started, release) = (control.join("started"), control.join("release"));
    let mut spec = scripted_validation(
        control,
        &[
            "import os, time",
            &format!("open({:?}, 'w').close()", started.display().to_string()),
            &format!(
                "while not os.path.exists({:?}): time.sleep(0.01)",
                release.display().to_string()
            ),
        ],
    );
    // Bounds a hang only: the test releases it.
    spec.timeout_secs = Some(120);
    spec
}

/// A transport timeout after the handler has accepted an approval must not
/// own the validation process. Hold the request wrapper open until the
/// controlled validation is running, then abort it and prove the detached
/// job reaches its terminal checkpoint.
#[tokio::test]
async fn aborted_review_transport_does_not_orphan_validating_integration() {
    let repo = init_repo();
    let db = Arc::new(Database::open_in_memory().unwrap());
    let state = AppState::new_defaults(
        Arc::new(RwLock::new(crate::core::config::default_config())),
        db.clone(),
        crate::DEFAULT_MAX_CONCURRENT_AGENTS,
    );
    let (_parent, _child, exec_id, _head, _path) =
        delivered_awaiting_review(&db, repo.path()).await;
    let control = tempfile::tempdir().unwrap();
    let (started, release) = (
        control.path().join("started"),
        control.path().join("release"),
    );
    let validation = held_validation(control.path());
    let run_id = exec_of(&db, &exec_id).await.orchestration_run_id;
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET validation_json = ?2 WHERE id = ?1",
            rusqlite::params![run_id, serde_json::to_string(&vec![validation])?],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let request = review_request(&exec_id, &review_approve(&db, &exec_id).await);
    let response_task = tokio::spawn(async move {
        let response = review(State(state), None, Json(request)).await;
        // Model middleware/response serialization still owns this future;
        // cancelling it models a caller disconnect after the handler has
        // accepted the review but while the detached validation is active.
        // It never finishes on its own: only the abort below ends it.
        std::future::pending::<()>().await;
        response
    });

    // The validation holds until released, so the abort lands inside it.
    wait_for_file(&started).await;
    wait_for_execution_status(&db, &exec_id, TaskExecutionStatus::Validating).await;
    response_task.abort();
    assert!(
        response_task.await.is_err(),
        "the request transport was cancelled"
    );
    std::fs::write(&release, "go").unwrap();

    let terminal = wait_for_execution_status(&db, &exec_id, TaskExecutionStatus::Done).await;
    assert!(terminal.integrated_sha.is_some());
    let id = exec_id.clone();
    let (reviews, validations): (i64, i64) = db
            .with_conn(move |conn| {
                Ok((
                    conn.query_row(
                        "SELECT COUNT(*) FROM task_execution_reviews WHERE task_execution_id = ?1",
                        [&id],
                        |row| row.get(0),
                    )?,
                    conn.query_row(
                        "SELECT COUNT(*) FROM task_execution_validation_runs WHERE task_execution_id = ?1",
                        [&id],
                        |row| row.get(0),
                    )?,
                ))
            })
            .await
            .unwrap();
    assert_eq!(reviews, 1);
    assert_eq!(validations, 1);
}

/// Two concurrent approve/retry transports can both enqueue work from the
/// same durable approval. The candidate-anchor status CAS lets exactly one
/// task cross into integration, so neither validation nor application is
/// duplicated.
#[tokio::test]
async fn concurrent_review_retries_share_one_durable_integration_claim() {
    let repo = init_repo();
    let db = Arc::new(Database::open_in_memory().unwrap());
    let state = AppState::new_defaults(
        Arc::new(RwLock::new(crate::core::config::default_config())),
        db.clone(),
        crate::DEFAULT_MAX_CONCURRENT_AGENTS,
    );
    let (_parent, _child, exec_id, _head, _path) =
        delivered_awaiting_review(&db, repo.path()).await;
    let control = tempfile::tempdir().unwrap();
    let (started, release) = (
        control.path().join("started"),
        control.path().join("release"),
    );
    let validation = held_validation(control.path());
    let run_id = exec_of(&db, &exec_id).await.orchestration_run_id;
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE orchestration_runs SET validation_json = ?2 WHERE id = ?1",
            rusqlite::params![run_id, serde_json::to_string(&vec![validation])?],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let decision = review_approve(&db, &exec_id).await;
    let first = tokio::spawn(review(
        State(state.clone()),
        None,
        Json(review_request(&exec_id, &decision)),
    ));
    let second = tokio::spawn(review(
        State(state),
        None,
        Json(review_request(&exec_id, &decision)),
    ));
    let (first, second) = tokio::join!(first, second);
    let first = first.unwrap().0;
    let second = second.unwrap().0;
    let outcomes = [&first, &second];
    let accepted = outcomes.iter().filter(|response| response.success).count();
    let conflicts = outcomes
        .iter()
        .filter(|response| response.error_code.as_deref() == Some("conflict"))
        .count();
    // Which answer the competing transport gets depends on when it reads
    // the execution: before the first task's `Approved -> Integrating`
    // claim it is an idempotent retry of the durable approval and succeeds
    // (see `decide_authorized_review`); after it, it is a conflict. Both are
    // correct. The invariant is durable, and asserted below: one review,
    // one integration claim, one validation.
    assert!(accepted >= 1, "the approval must be accepted");
    assert_eq!(
        accepted + conflicts,
        2,
        "the competing transport either retries the approval or meets the claim"
    );

    // Both transports answered while the validation was held.
    wait_for_file(&started).await;
    std::fs::write(&release, "go").unwrap();
    let terminal = wait_for_execution_status(&db, &exec_id, TaskExecutionStatus::Done).await;
    assert!(terminal.integrated_sha.is_some());
    let id = exec_id.clone();
    let (reviews, validations, integrations): (i64, i64, i64) = db
            .with_conn(move |conn| {
                Ok((
                    conn.query_row(
                        "SELECT COUNT(*) FROM task_execution_reviews WHERE task_execution_id = ?1",
                        [&id],
                        |row| row.get(0),
                    )?,
                    conn.query_row(
                        "SELECT COUNT(*) FROM task_execution_validation_runs WHERE task_execution_id = ?1",
                        [&id],
                        |row| row.get(0),
                    )?,
                    conn.query_row(
                        "SELECT COUNT(*) FROM task_execution_events \
                         WHERE task_execution_id = ?1 \
                           AND from_status = 'Approved' AND to_status = 'Integrating'",
                        [&id],
                        |row| row.get(0),
                    )?,
                ))
            })
            .await
            .unwrap();
    assert_eq!(reviews, 1, "the review decision remains idempotent");
    assert_eq!(integrations, 1, "only one task wins the durable claim");
    assert_eq!(
        validations, 1,
        "the losing task never records a duplicate validation"
    );
}

/// DoD-5, the distinguishing case: a worker may deliver an ABBREVIATED head_sha; approve
/// must NOT false-refuse it. resolve_commit normalizes short↔long on both sides, so a
/// 8-char delivered sha compares equal to the full worktree HEAD.
#[tokio::test]
async fn approve_accepts_an_abbreviated_delivered_sha() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task_ref, parent_id, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let head = git_rev(Path::new(&path), "HEAD");
    let short = head[..8].to_string();
    assert_ne!(short, head, "the abbreviated sha differs from the full one");

    deliver_worker_manifest(
        &db,
        &exec_id,
        "ClaudeCode",
        "sess-a",
        &manifest_json_with_files_for_dod(
            &short,
            serde_json::json!([]),
            &dod_id_for_execution(&db, &exec_id).await,
            true,
        ),
    )
    .await
    .unwrap();
    seed_cli_session(&db, 102, &parent_id, "sess-b").await;

    // The stored delivered head is the SHORT form — proving the normalization does the work.
    let stored = db
        .with_conn({
            let e = exec_id.clone();
            move |conn| crate::db::worker_deliveries::get_delivery(conn, &e, 0)
        })
        .await
        .unwrap()
        .unwrap();
    assert_eq!(stored.head_sha, short);

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_approve(&db, &exec_id).await,
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    assert!(
        matches!(
            outcome,
            ReviewOutcome::Reviewed {
                verdict: ReviewVerdict::Approve,
                ..
            }
        ),
        "an abbreviated sha equal to HEAD must approve, not drift-refuse: {outcome:?}"
    );
}

/// DoD-5: approve is refused when the worktree HEAD moved since delivery, and NOTHING
/// moves — a refused approve leaves the execution AwaitingReview with no review row.
#[tokio::test]
async fn approve_is_refused_when_head_drifted() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_parent, _child, exec_id, _head, path) = delivered_awaiting_review(&db, repo.path()).await;

    // The worker advances the branch after delivery → the reviewed state drifted.
    git(
        Path::new(&path),
        &["commit", "--allow-empty", "-m", "drift"],
    );

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_approve(&db, &exec_id).await,
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    match outcome {
        ReviewOutcome::ApproveBlocked {
            reason: ApproveBlockReason::HeadDrifted { delivered, current },
        } => assert_ne!(delivered, current, "the two shas differ"),
        other => panic!("expected ApproveBlocked/HeadDrifted, got {other:?}"),
    }
    assert_eq!(
        exec_of(&db, &exec_id).await.status,
        TaskExecutionStatus::AwaitingReview,
        "a refused approve does not move the execution"
    );
    assert!(
        review_row(&db, &exec_id).await.is_none(),
        "no review persisted on refusal"
    );
}

#[tokio::test]
async fn approve_is_refused_when_the_worktree_became_dirty_after_delivery() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_parent, _child, exec_id, _head, path) = delivered_awaiting_review(&db, repo.path()).await;
    std::fs::write(Path::new(&path).join("late-uncommitted.txt"), "late\n").unwrap();

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_approve(&db, &exec_id).await,
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    match outcome {
        ReviewOutcome::ApproveBlocked {
            reason: ApproveBlockReason::WorktreeDirty { files },
        } => assert!(
            files
                .iter()
                .any(|file| file.contains("late-uncommitted.txt")),
            "the refusal must name the dirty path: {files:?}"
        ),
        other => panic!("expected ApproveBlocked/WorktreeDirty, got {other:?}"),
    }
    assert_eq!(
        exec_of(&db, &exec_id).await.status,
        TaskExecutionStatus::AwaitingReview
    );
    assert!(review_row(&db, &exec_id).await.is_none());
}

#[tokio::test]
async fn cancellation_ack_requires_the_exact_registry_guard_to_finish() {
    let registry = std::sync::Arc::new(std::sync::Mutex::new(std::collections::HashMap::new()));
    let guard = crate::CancelGuard::insert(&registry, "dispatch-under-test");
    guard.token.cancel();

    assert!(
        !wait_for_cancelled_dispatches_to_settle(
            &registry,
            &["dispatch-under-test".into()],
            std::time::Duration::from_millis(10),
        )
        .await,
        "a cancelled token is not proof that its runtime has finished"
    );

    drop(guard);
    assert!(
        wait_for_cancelled_dispatches_to_settle(
            &registry,
            &["dispatch-under-test".into()],
            std::time::Duration::from_millis(10),
        )
        .await,
        "dropping the exact runtime guard acknowledges termination"
    );
}

#[tokio::test]
async fn cancel_execution_receipt_reports_signal_and_runtime_ack_without_touching_a_peer() {
    let repo = init_repo();
    let db = std::sync::Arc::new(Database::open_in_memory().unwrap());
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let execution = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref.clone(),
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("cancel-receipt-runtime-ack".into()),
        },
    )
    .await
    .unwrap();
    let worktree_path = managed_worktree_path(&db, &execution.id).await;
    // KT-1267 — provisioning started the task; a cancel must not undo that.
    let task_status_before = {
        let task_ref = task_ref.clone();
        db.with_conn(move |conn| {
            Ok(crate::db::planning::get_task(conn, &task_ref)?
                .unwrap()
                .summary
                .status)
        })
        .await
        .unwrap()
    };
    assert_ne!(task_status_before, PlanningTaskStatus::Todo);
    let dispatch_id = execution.dispatch_job_id.clone().unwrap();
    let state = AppState::new_defaults(
        std::sync::Arc::new(tokio::sync::RwLock::new(
            crate::core::config::default_config(),
        )),
        db.clone(),
        crate::DEFAULT_MAX_CONCURRENT_AGENTS,
    );

    let worker_guard = crate::CancelGuard::insert(&state.cancel_registry, dispatch_id);
    let worker_token = worker_guard.token.clone();
    let peer_guard = crate::CancelGuard::insert(&state.cancel_registry, "peer-dispatch");
    let peer_token = peer_guard.token.clone();
    let worker_finished = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let worker_finished_in_task = worker_finished.clone();
    let worker = tokio::spawn(async move {
        worker_token.cancelled().await;
        worker_finished_in_task.store(true, std::sync::atomic::Ordering::SeqCst);
        drop(worker_guard);
    });

    let response = cancel_execution(
        State(state),
        Path(execution.id.clone()),
        Json(CancelExecutionRequest {
            reason: "test cancellation".into(),
            cleanup_policy: Some(crate::models::CancellationCleanupPolicy::Preserve),
        }),
    )
    .await
    .0;
    worker.await.unwrap();

    assert!(
        response.success,
        "cancellation must succeed: {:?}",
        response.error
    );
    let receipt = response.data.expect("cancellation receipt");
    assert_eq!(receipt.execution.status, TaskExecutionStatus::Cancelled);
    assert_eq!(receipt.cancellation_signal_sent, Some(true));
    assert_eq!(receipt.termination_confirmed, Some(true));
    assert!(receipt
        .outcome
        .as_deref()
        .is_some_and(|value| value.contains("policy=preserve")));
    let task_status_after = db
        .with_conn(move |conn| {
            Ok(crate::db::planning::get_task(conn, &task_ref)?
                .unwrap()
                .summary
                .status)
        })
        .await
        .unwrap();
    assert_eq!(task_status_after, task_status_before);
    let expected_note = format!("task status kept: {}", task_status_before.as_str());
    assert!(
        receipt.outcome.as_deref().is_some_and(
            |value| value.contains(&expected_note) && value.contains("task_update status=todo")
        ),
        "the receipt says the status is kept and how to relaunch: {:?}",
        receipt.outcome
    );
    assert!(worker_finished.load(std::sync::atomic::Ordering::SeqCst));
    assert!(!peer_token.is_cancelled(), "a sibling dispatch is isolated");
    assert!(
        std::path::Path::new(&worktree_path).exists(),
        "Preserve keeps the worker checkout"
    );
    drop(peer_guard);
}

/// KT-396 — the regression the task names: a cancellation under `Preserve`
/// keeps the worktree and its sources, and `target/` is reclaimed. Before
/// the fix, cancellation was the one terminal path that never called the
/// reclaim, and task-kt-377-49a08eeb kept its 39 MiB.
#[tokio::test]
async fn a_cancelled_preserved_worktree_loses_its_target_and_nothing_else() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let worktree = std::path::Path::new(&path);

    // Build artefacts, and a source file that must survive.
    std::fs::create_dir_all(worktree.join("target/debug")).unwrap();
    std::fs::write(worktree.join("target/debug/kronn"), b"artefact").unwrap();
    std::fs::write(worktree.join("work-in-progress.rs"), "fn wip() {}\n").unwrap();

    // Cancel the tree exactly as the handler does, then settle the workspace.
    let eid = exec_id.clone();
    db.with_conn(move |conn| {
        crate::db::orchestration::cancel_execution_tree(conn, &eid, "test", &backend_actor())
    })
    .await
    .unwrap();
    let workspace = {
        let eid = exec_id.clone();
        db.with_conn(move |conn| {
            crate::db::discussion_workspaces::get_managed_for_execution(conn, &eid)
        })
        .await
        .unwrap()
    };
    let outcome = settle_cancelled_workspace(
        &db,
        &exec_id,
        crate::models::CancellationCleanupPolicy::Preserve,
        workspace,
        Some(repo.path().to_string_lossy().to_string()),
    )
    .await;
    assert!(outcome.contains("policy=preserve"), "{outcome}");

    // The policy's promise, then the fix's: sources and worktree stay,
    // target/ is gone.
    assert!(
        worktree.exists(),
        "a Preserve cancellation keeps the worktree"
    );
    assert!(
        worktree.join("work-in-progress.rs").exists(),
        "and the sources in it"
    );
    assert!(
        !worktree.join("target").exists(),
        "but the rebuildable artefacts are reclaimed"
    );

    // Every attempt is audited, success included.
    let audited: i64 = db
        .with_conn(move |conn| {
            Ok(conn.query_row(
                "SELECT COUNT(*) FROM task_execution_events \
                     WHERE action IN ('build_artifacts_reclaimed', 'build_artifacts_refused')",
                [],
                |row| row.get(0),
            )?)
        })
        .await
        .unwrap();
    assert!(audited >= 1, "the reclaim must leave a durable event");
}

/// KT-1256 — a lane target as a worker leaves it, outside the worktree.
fn seed_lane_target_of(repo: &Path, worktree: &str) -> std::path::PathBuf {
    let lane_target =
        worktree::lane_target_for_worktree(repo, std::path::Path::new(worktree)).unwrap();
    std::fs::create_dir_all(lane_target.join("debug")).unwrap();
    std::fs::write(lane_target.join("debug/kronn"), vec![0u8; 2048]).unwrap();
    lane_target
}

async fn lane_target_events(db: &Database, action: &'static str) -> i64 {
    db.with_conn(move |conn| {
        Ok(conn.query_row(
            "SELECT COUNT(*) FROM task_execution_events WHERE action = ?1",
            [action],
            |row| row.get(0),
        )?)
    })
    .await
    .unwrap()
}

/// KT-1256 — DoD 1: an integrated execution's clean worktree is removed
/// and its lane target goes with it; the main target stays.
#[tokio::test]
async fn an_integrated_executions_lane_target_is_removed_with_its_clean_worktree() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let lane_target = seed_lane_target_of(repo.path(), &path);
    let main_debug = repo.path().join("target/debug");
    std::fs::create_dir_all(&main_debug).unwrap();
    let head = String::from_utf8(
        crate::core::cmd::git_cmd()
            .args(["rev-parse", "HEAD"])
            .current_dir(&path)
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap()
    .trim()
    .to_string();
    let execution = exec_of(&db, &exec_id).await;

    cleanup_integrated_execution(&db, &execution, repo.path(), &path, &head)
        .await
        .unwrap();

    assert!(
        !std::path::Path::new(&path).exists(),
        "the clean worktree is removed"
    );
    assert!(!lane_target.exists(), "and its lane target with it");
    assert!(main_debug.exists(), "the main target is not a lane");
    assert_eq!(
        lane_target_events(&db, "lane_target_reclaimed").await,
        1,
        "the reclaim is audited against the execution"
    );
}

