/// KT-1676 — a managed worktree removed outside Kronn is no longer recorded
/// as attached. A worker's own stays `missing` (lineage and branch kept, so
/// the execution is still resumable); a finished one is retired. A worktree
/// that is still there is left alone, and the dead Git entry is pruned.
#[tokio::test]
async fn a_worktree_removed_outside_kronn_is_marked_gone() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, live_exec) = attached_cli_worker(&db, repo.path()).await;
    let live_path = managed_worktree_path(&db, &live_exec).await;
    let branch = exec_of(&db, &live_exec).await.child_branch.expect("branch");
    let project = project_of_execution(&db, &live_exec).await;
    let (done_exec, done_session) = another_attached_worker(&db, &project.id, 2).await;
    let done_path = managed_worktree_path(&db, &done_exec).await;
    let (kept_exec, _) = another_attached_worker(&db, &project.id, 3).await;
    let kept_path = managed_worktree_path(&db, &kept_exec).await;
    force_status(&db, &done_exec, "Failed").await;
    leave_session(&db, done_session).await;

    assert_eq!(reconcile_missing_managed_checkouts(&db).await.unwrap(), 0);

    for path in [&live_path, &done_path] {
        let removed = git(repo.path(), &["worktree", "remove", "--force", path]);
        assert!(removed.status.success(), "{removed:?}");
    }
    assert_eq!(reconcile_missing_managed_checkouts(&db).await.unwrap(), 2);

    let live = workspace_of(&db, &live_exec).await;
    assert_eq!(live.state, "missing");
    assert_eq!(live.branch, branch, "the lineage stays");
    let done = workspace_of(&db, &done_exec).await;
    assert_eq!(done.state, "detached");
    assert_eq!(done.canonical_path, None);
    assert_eq!(workspace_of(&db, &kept_exec).await.state, "attached");
    assert!(std::path::Path::new(&kept_path).exists());
    let id = live_exec.clone();
    let events = db
        .with_conn(move |conn| crate::db::orchestration::list_execution_events(conn, &id))
        .await
        .unwrap();
    assert_eq!(
        events
            .iter()
            .filter(|event| event.action == "worktree_missing")
            .count(),
        1
    );
    assert_eq!(
        git_rev(repo.path(), &format!("refs/heads/{branch}")).len(),
        40
    );
    let listed =
        String::from_utf8_lossy(&git(repo.path(), &["worktree", "list"]).stdout).to_string();
    assert!(!listed.contains(&dir_name(&live_path)), "{listed}");

    // Already settled: a second pass finds nothing to do.
    assert_eq!(reconcile_missing_managed_checkouts(&db).await.unwrap(), 0);
}

/// KT-1676 — the reported case: 65 worktrees, one over the cap, eight of
/// them clean checkouts of finished or closed tasks. The launch reclaims
/// them and is accepted; the dirty one and the one a running task uses stay.
#[tokio::test]
async fn a_launch_at_65_worktrees_reclaims_the_eight_that_are_finished() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, first) = attached_cli_worker(&db, repo.path()).await;
    let project = project_of_execution(&db, &first).await;
    let mut reclaimable = vec![(first, 101)];
    for n in 2..=8 {
        reclaimable.push(another_attached_worker(&db, &project.id, n).await);
    }
    let (dirty_exec, dirty_session) = another_attached_worker(&db, &project.id, 9).await;
    let (running_exec, _) = another_attached_worker(&db, &project.id, 10).await;
    let dirty_path = managed_worktree_path(&db, &dirty_exec).await;
    let running_path = managed_worktree_path(&db, &running_exec).await;
    std::fs::write(
        std::path::Path::new(&dirty_path).join("README.md"),
        "# edited",
    )
    .unwrap();
    let mut paths = Vec::new();
    for (index, (exec_id, session)) in reclaimable.iter().enumerate() {
        paths.push(managed_worktree_path(&db, exec_id).await);
        leave_session(&db, *session).await;
        match index {
            // Finished the regular way.
            0..=3 => {
                force_status(&db, exec_id, ["Done", "Failed", "Cancelled", "Done"][index]).await
            }
            // Closed by hand, the execution never finished (KT-1605).
            _ => {
                set_task_status_of(&db, exec_id, "done").await;
            }
        }
    }
    force_status(&db, &dirty_exec, "Cancelled").await;
    leave_session(&db, dirty_session).await;

    // main + 8 + dirty + running = 11 real worktrees; the rest stand for
    // the unrelated ones of the ticket's repository: 65 in all.
    reclaim_over_catalogue_cap(&db, &project, measure_with_excess::<54>).await;
    let verdict = {
        let project = project.clone();
        db.with_conn(move |conn| {
            Ok(claude_catalogue_verdict(
                conn,
                &project,
                measure_with_excess::<54>,
            ))
        })
        .await
        .unwrap()
    };

    assert_eq!(verdict, Ok(()), "57 worktrees are within the cap");
    for path in &paths {
        assert!(!std::path::Path::new(path).exists(), "reclaimed: {path}");
    }
    assert!(std::path::Path::new(&dirty_path).exists(), "dirty: kept");
    assert!(
        std::path::Path::new(&running_path).exists(),
        "running: kept"
    );
}

/// KT-1676 — when the sweep cannot bring the count under the cap the
/// refusal names every worktree that blocks, why Kronn kept it, and what
/// frees it: a dirty finished checkout, one a running task uses and one
/// Kronn never created. No path is exposed.
#[tokio::test]
async fn a_refusal_names_what_blocks_and_how_to_free_it() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (dirty_exec, dirty_path, _lane) = finished_dirty_execution(&db, repo.path()).await;
    let project = project_of_execution(&db, &dirty_exec).await;
    let (running_exec, _) = another_attached_worker(&db, &project.id, 2).await;
    let running_path = managed_worktree_path(&db, &running_exec).await;
    let foreign = repo.path().join("../kt1676-foreign-worktree");
    let added = git(
        repo.path(),
        &[
            "worktree",
            "add",
            "-b",
            "kt1676-foreign",
            foreign.to_str().unwrap(),
        ],
    );
    assert!(added.status.success(), "{added:?}");

    reclaim_over_catalogue_cap(&db, &project, measure_with_excess::<64>).await;
    let error = {
        let project = project.clone();
        db.with_conn(move |conn| {
            Ok(claude_catalogue_verdict(
                conn,
                &project,
                measure_with_excess::<64>,
            ))
        })
        .await
        .unwrap()
        .unwrap_err()
    };

    assert!(error.contains("max_git_worktrees=64"), "{error}");
    assert!(
        error.contains(&format!(
            "{} (finished task, not clean",
            dir_name(&dirty_path)
        )),
        "{error}"
    );
    assert!(
        error.contains(&format!("{} (task still running)", dir_name(&running_path))),
        "{error}"
    );
    assert!(
        error.contains("kt1676-foreign-worktree (not created by Kronn)"),
        "{error}"
    );
    assert!(error.contains("git worktree remove <name>"), "{error}");
    assert!(error.contains("close their task"), "{error}");
    assert!(!error.contains(repo.path().to_str().unwrap()), "{error}");
    let _ = git(
        repo.path(),
        &["worktree", "remove", "--force", foreign.to_str().unwrap()],
    );
}

/// KT-1397 — `finished_at` does not prove the checkout idle: a file written
/// just before the sweep keeps an old terminal execution's checkout and lane
/// for the idle window, with a reason recorded once; the same checkout with
/// no idle window is released.
#[tokio::test]
async fn a_recently_written_checkout_keeps_its_worktree_for_the_idle_window() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (exec_id, path, lane_target) = finished_dirty_execution(&db, repo.path()).await;
    // The execution finished long ago.
    let id = exec_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE task_executions SET finished_at = '2020-01-01T00:00:00Z' WHERE id = ?1",
            rusqlite::params![id],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let recent = std::path::Path::new(&path).join("recent-work.txt");
    std::fs::write(&recent, "recent edit after the execution finished\n").unwrap();

    for _ in 0..2 {
        let mut report = OrchestrationBootReport::default();
        release_terminal_worktrees(&db, std::time::Duration::from_secs(3600), &mut report).await;
        assert_eq!(report.terminal_worktrees_released, 0, "{report:?}");
        assert_eq!(report.terminal_worktrees_kept, 1, "{report:?}");
    }

    assert!(recent.exists());
    assert!(lane_target.exists());
    let reasons = kept_reasons(&db, &exec_id).await;
    assert_eq!(reasons.len(), 1, "recorded once: {reasons:?}");
    assert!(reasons[0].contains("written within"), "{reasons:?}");

    let mut report = OrchestrationBootReport::default();
    release_terminal_worktrees(&db, std::time::Duration::ZERO, &mut report).await;
    assert_eq!(report.terminal_worktrees_released, 1, "{report:?}");
    assert!(!std::path::Path::new(&path).exists());
    assert!(!lane_target.exists());
}

/// KT-1397 — staged-only work is saved by the sweep too: both patches land
/// in the execution's evidence directory and the event names them.
#[tokio::test]
async fn the_sweep_saves_staged_only_work_before_releasing() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (exec_id, path, _lane) = finished_dirty_execution(&db, repo.path()).await;
    let wt = std::path::Path::new(&path);
    let original = git(wt, &["show", "HEAD:README.md"]).stdout;
    std::fs::write(wt.join("README.md"), "STAGED_WORK_TO_PRESERVE\n").unwrap();
    assert!(git(wt, &["add", "README.md"]).status.success());
    std::fs::write(wt.join("README.md"), original).unwrap();
    let _ = std::fs::remove_dir_all(terminal_evidence_dir(&exec_id).unwrap());

    let mut report = OrchestrationBootReport::default();
    release_terminal_worktrees(&db, std::time::Duration::ZERO, &mut report).await;

    assert_eq!(report.terminal_worktrees_released, 1, "{report:?}");
    assert!(!wt.exists());
    let staged = terminal_evidence_dir(&exec_id)
        .unwrap()
        .join(worktree::RELEASED_WORKTREE_STAGED_PATCH);
    assert!(std::fs::read_to_string(staged)
        .unwrap()
        .contains("STAGED_WORK_TO_PRESERVE"));
    assert_eq!(lane_target_events(&db, "worktree_released").await, 1);
}

/// KT-1397 — DoD 1/2: a Cancelled (kept by policy) and a Failed execution
/// are released by the boot pass; a recent finish waits for its idle time.
#[tokio::test]
async fn the_boot_pass_releases_finished_worktrees_and_their_lanes() {
    for status in ["Cancelled", "Failed"] {
        let repo = init_repo();
        let db = Database::open_in_memory().unwrap();
        let (_task, _parent, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
        let path = managed_worktree_path(&db, &exec_id).await;
        let branch = exec_of(&db, &exec_id).await.child_branch.expect("branch");
        let lane_target = seed_lane_target_of(repo.path(), &path);
        std::fs::write(std::path::Path::new(&path).join("wip.txt"), "wip").unwrap();
        if status == "Cancelled" {
            let outcome = cancelled_with_policy(
                &db,
                repo.path(),
                &exec_id,
                crate::models::CancellationCleanupPolicy::Preserve,
            )
            .await;
            assert!(!outcome.contains("removed"), "{outcome}");
        }
        force_status(&db, &exec_id, status).await;
        worker_session_left(&db).await;
        assert!(
            std::path::Path::new(&path).exists(),
            "{status}: still there"
        );

        // Finished long ago, but the host asks for a year of idle time.
        let mut report = OrchestrationBootReport::default();
        release_terminal_worktrees(
            &db,
            std::time::Duration::from_secs(100 * 365 * 24 * 3600),
            &mut report,
        )
        .await;
        assert_eq!(report.terminal_worktrees_kept, 1, "{status}");
        assert!(std::path::Path::new(&path).exists());

        let mut report = OrchestrationBootReport::default();
        release_terminal_worktrees(&db, std::time::Duration::ZERO, &mut report).await;

        assert_eq!(
            report.terminal_worktrees_released, 1,
            "{status}: {report:?}"
        );
        assert!(!std::path::Path::new(&path).exists(), "{status}: released");
        assert!(!lane_target.exists(), "{status}: lane purged");
        assert_eq!(
            git_rev(repo.path(), &format!("refs/heads/{branch}")).len(),
            40
        );
        let saved = std::fs::read_to_string(
            terminal_evidence_dir(&exec_id)
                .unwrap()
                .join(worktree::RELEASED_WORKTREE_PATCH),
        )
        .expect("diff saved");
        assert!(saved.contains("wip.txt"), "{status}");
    }
}

/// KT-1397 — DoD 2: the boot pass never touches a non-terminal execution
/// or a workspace Kronn does not manage.
#[tokio::test]
async fn the_boot_pass_never_touches_live_or_unmanaged_worktrees() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let lane_target = seed_lane_target_of(repo.path(), &path);
    std::fs::write(std::path::Path::new(&path).join("wip.txt"), "wip").unwrap();
    let mut report = OrchestrationBootReport::default();

    // Working: not a finished state.
    release_terminal_worktrees(&db, std::time::Duration::ZERO, &mut report).await;
    assert_eq!(report.terminal_worktrees_released, 0);
    assert!(std::path::Path::new(&path).exists());

    force_status(&db, &exec_id, "Cancelled").await;

    // Finished and unused, yet the workspace is not Kronn's.
    worker_session_left(&db).await;
    db.with_conn(|conn| {
        conn.execute(
            "UPDATE discussion_workspaces SET ownership = 'external'
                  WHERE task_execution_id IS NOT NULL",
            [],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    release_terminal_worktrees(&db, std::time::Duration::ZERO, &mut report).await;
    assert_eq!(report.terminal_worktrees_released, 0);
    assert!(std::path::Path::new(&path).exists());
    assert!(lane_target.exists());
}

/// What the DB-driven sweep tests share: an execution with a managed
/// worktree, its lane target stamped as provisioning does, and an
/// unmarked `wt-*` a human built.
struct LaneFixture {
    repo: tempfile::TempDir,
    db: Database,
    exec_id: String,
    path: String,
    project_id: String,
    lane_target: std::path::PathBuf,
    human_target: std::path::PathBuf,
}

async fn lane_fixture() -> LaneFixture {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_task, _parent, _child, exec_id) = attached_cli_worker(&db, repo.path()).await;
    let path = managed_worktree_path(&db, &exec_id).await;
    let project_id = {
        let eid = exec_id.clone();
        db.with_conn(move |conn| {
            crate::db::discussion_workspaces::get_managed_for_execution(conn, &eid)
        })
        .await
        .unwrap()
        .expect("workspace")
        .project_id
    };
    let lane_target =
        worktree::mark_lane_target(repo.path(), std::path::Path::new(&path), &exec_id).unwrap();
    std::fs::create_dir_all(lane_target.join("debug")).unwrap();
    std::fs::write(lane_target.join("debug/kronn"), vec![0u8; 2048]).unwrap();
    // The principal's own integration target: a `wt-*` with no workspace
    // row and no marker.
    let human_target = repo.path().join("target/wt-0151-integration");
    std::fs::create_dir_all(human_target.join("debug")).unwrap();
    std::fs::write(human_target.join("debug/kronn"), b"hand built").unwrap();
    LaneFixture {
        repo,
        db,
        exec_id,
        path,
        project_id,
        lane_target,
        human_target,
    }
}

impl LaneFixture {
    async fn sweep(&self, scope: worktree::LaneSweepScope) -> worktree::LaneTargetSweep {
        sweep_project_lane_targets(&self.db, &self.project_id, self.repo.path(), scope)
            .await
            .unwrap()
    }

    async fn cancel(&self) {
        let eid = self.exec_id.clone();
        self.db
            .with_conn(move |conn| {
                crate::db::orchestration::cancel_execution_tree(
                    conn,
                    &eid,
                    "test",
                    &backend_actor(),
                )
            })
            .await
            .unwrap();
    }
}

/// KT-1256 — an unmarked `wt-*` is never Kronn's to delete, finished
/// execution or not: it is reported and left exactly as it was.
#[tokio::test]
async fn an_unmarked_wt_directory_survives_the_sweep() {
    let fx = lane_fixture().await;
    fx.cancel().await;

    let sweep = fx
        .sweep(worktree::LaneSweepScope::WorktreeGoneOrClean)
        .await;

    assert!(fx.human_target.join("debug/kronn").exists());
    assert!(sweep.unmarked.contains(&fx.human_target), "{sweep:?}");
    assert!(!sweep
        .removed
        .iter()
        .any(|(_, r)| r.target_path == fx.human_target));
}

/// KT-1256 — a marked lane of an execution that is still alive stays.
#[tokio::test]
async fn a_marked_lane_of_a_live_execution_survives_the_sweep() {
    let fx = lane_fixture().await;
    assert!(!exec_of(&fx.db, &fx.exec_id).await.status.is_terminal());

    let sweep = fx
        .sweep(worktree::LaneSweepScope::WorktreeGoneOrClean)
        .await;

    assert!(fx.lane_target.join("debug/kronn").exists());
    assert!(sweep.removed.is_empty(), "{sweep:?}");
    assert_eq!(sweep.claimed.len(), 1, "{sweep:?}");
    assert_eq!(sweep.claimed[0].0, fx.lane_target);
}

/// KT-1256 — a finished execution whose dirty worktree is preserved keeps
/// its lane target with it.
#[tokio::test]
async fn a_marked_lane_of_a_finished_execution_with_a_kept_dirty_worktree_survives() {
    let fx = lane_fixture().await;
    std::fs::write(
        std::path::Path::new(&fx.path).join("work-in-progress.rs"),
        "fn wip() {}\n",
    )
    .unwrap();
    fx.cancel().await;
    assert!(exec_of(&fx.db, &fx.exec_id).await.status.is_terminal());

    let sweep = fx
        .sweep(worktree::LaneSweepScope::WorktreeGoneOrClean)
        .await;

    assert!(fx.lane_target.join("debug/kronn").exists(), "{sweep:?}");
    assert!(
        sweep.removed.is_empty() && sweep.would_remove.is_empty(),
        "{sweep:?}"
    );
    assert!(
        sweep
            .kept
            .iter()
            .any(|(path, reason)| path == &fx.lane_target && reason.contains("uncommitted")),
        "{sweep:?}"
    );
    assert_eq!(lane_target_events(&fx.db, "lane_target_reclaimed").await, 0);
}

/// KT-1256 — DoD 2: a marked lane of a finished execution whose worktree
/// is gone is removed, reported by the dry run first, and audited.
#[tokio::test]
async fn a_marked_lane_of_a_finished_execution_with_a_removed_worktree_is_removed() {
    let fx = lane_fixture().await;
    fx.cancel().await;
    worktree::remove_discussion_worktree(fx.repo.path(), &fx.path, true).unwrap();
    assert!(!std::path::Path::new(&fx.path).exists());

    let dry = fx.sweep(worktree::LaneSweepScope::ReportOnly).await;
    assert_eq!(dry.would_remove.len(), 1, "{dry:?}");
    assert!(dry.would_remove[0].1.bytes_reclaimed > 0);
    assert!(fx.lane_target.exists(), "a dry run deletes nothing");

    // Boot's scope: the worktree is gone, so the lane goes.
    let sweep = fx.sweep(worktree::LaneSweepScope::WorktreeGone).await;

    assert!(!fx.lane_target.exists(), "{sweep:?}");
    assert_eq!(sweep.removed.len(), 1, "{sweep:?}");
    assert!(sweep.bytes_removed() > 0);
    assert!(fx.human_target.exists(), "the unmarked target is untouched");
    assert_eq!(
        lane_target_events(&fx.db, "lane_target_reclaimed").await,
        1,
        "the removal is audited against the execution the marker names"
    );
}

