/// KT-385: a native worker cannot be woken through wait_for_peer. Its rework
/// therefore advances the attempt and queues a new durable dispatch in the
/// same transaction as request_changes. This is the real Ollama pilot path.
#[tokio::test]
async fn request_changes_redispatches_a_native_worker_as_a_new_attempt() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (_parent, child_id, exec_id, _head, _path) =
        delivered_awaiting_review(&db, repo.path()).await;
    let e = exec_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE task_executions SET worker_target_kind = 'agent', \
                     worker_cli_session_id = NULL, worker_agent_type = 'Ollama' WHERE id = ?1",
            [&e],
        )?;
        Ok(())
    })
    .await
    .unwrap();

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_request_changes("commit puis relivre"),
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    let execution = match outcome {
        ReviewOutcome::Reviewed {
            verdict: ReviewVerdict::RequestChanges,
            execution,
        } => execution,
        other => panic!("expected native rework, got {other:?}"),
    };
    assert_eq!(execution.status, TaskExecutionStatus::Working);
    assert_eq!(execution.attempt_no, 1);
    let dispatch_id = execution.dispatch_job_id.expect("fresh dispatch attached");

    let dispatch_for_lookup = dispatch_id.clone();
    let (status, dedupe, discussion_id, trigger_message_id, target) = db
        .with_conn(move |conn| {
            let job = crate::db::agent_dispatch::get(conn, &dispatch_for_lookup)?
                .context("native rework dispatch vanished")?;
            let target =
                crate::db::discussions::list_message_targets(conn, &job.trigger_message_id)?
                    .into_iter()
                    .next()
                    .context("findings lost their worker target")?;
            Ok((
                job.status,
                job.dedupe_key,
                job.discussion_id,
                job.trigger_message_id,
                target,
            ))
        })
        .await
        .unwrap();
    assert_eq!(status, crate::db::agent_dispatch::DispatchStatus::Pending);
    assert_eq!(dedupe, format!("orch-rework:{exec_id}:1"));
    assert_eq!(discussion_id, child_id);
    assert_eq!(
        trigger_message_id,
        format!("orch-review-findings:{exec_id}:0")
    );
    assert_eq!(target.kind, MessageTargetKind::Agent);
    assert_eq!(target.agent_type, AgentType::Ollama);

    let manifest = projected_manifest_for_execution(&db, &exec_id).await;
    let delivered = deliver_native_worker_manifest(
        &db,
        &exec_id,
        NativeExecutionCaller {
            discussion_id: &child_id,
            agent_type: &AgentType::Ollama,
            source_message_id: Some(&trigger_message_id),
            alias: "Ollama",
            actor_session_id: Some("native-rework-1"),
        },
        &dispatch_id,
        &manifest,
    )
    .await
    .unwrap();
    assert!(matches!(delivered, DeliverOutcome::Delivered { .. }));

    let second = decide_review(
        &db,
        &exec_id,
        &review_request_changes("second native rework cycle"),
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    let second_execution = match second {
        ReviewOutcome::Reviewed {
            verdict: ReviewVerdict::RequestChanges,
            execution,
        } => execution,
        other => panic!("expected second native rework, got {other:?}"),
    };
    assert_eq!(second_execution.attempt_no, 2);
    let second_dispatch = second_execution
        .dispatch_job_id
        .expect("second rework dispatch attached");
    assert_ne!(
        second_dispatch, dispatch_id,
        "each rework gets a new dispatch"
    );
    let second_dispatch_for_lookup = second_dispatch.clone();
    let second_trigger = db
        .with_conn(move |conn| {
            Ok(
                crate::db::agent_dispatch::get(conn, &second_dispatch_for_lookup)?
                    .context("second native rework dispatch vanished")?
                    .trigger_message_id,
            )
        })
        .await
        .unwrap();
    let manifest = projected_manifest_for_execution(&db, &exec_id).await;
    let stale = deliver_native_worker_manifest(
        &db,
        &exec_id,
        NativeExecutionCaller {
            discussion_id: &child_id,
            agent_type: &AgentType::Ollama,
            source_message_id: Some(&trigger_message_id),
            alias: "Ollama",
            actor_session_id: Some("stale-native-rework-1"),
        },
        &dispatch_id,
        &manifest,
    )
    .await
    .unwrap();
    assert!(matches!(stale, DeliverOutcome::NotAddressed));
    let execution_for_delivery = exec_id.clone();
    assert!(
        db.with_conn(move |conn| {
            crate::db::worker_deliveries::get_delivery(conn, &execution_for_delivery, 2)
        })
        .await
        .unwrap()
        .is_none(),
        "the stale dispatch must not create the current attempt delivery"
    );
    let delivered = deliver_native_worker_manifest(
        &db,
        &exec_id,
        NativeExecutionCaller {
            discussion_id: &child_id,
            agent_type: &AgentType::Ollama,
            source_message_id: Some(&second_trigger),
            alias: "Ollama",
            actor_session_id: Some("native-rework-2"),
        },
        &second_dispatch,
        &manifest,
    )
    .await
    .unwrap();
    assert!(matches!(delivered, DeliverOutcome::Delivered { .. }));
}

const STYLE_PATH: &str = "tc.justin.scss";
const STYLE_BASE: &str = ".tc-justin {\n  display: flex;\n}\n\
        .tc-justin__title {\n  margin: 0;\n}\n\
        .tc-justin__list-gradient {\n  background: linear-gradient(red, blue);\n}\n";
const STYLE_NEIGHBOUR: &str =
    ".tc-justin__list-gradient {\n  background: linear-gradient(red, blue);\n}\n";

fn style_scope(start_line: u32, end_line: u32) -> TaskWorkerScope {
    TaskWorkerScope::PrelocalizedEdit {
        path: STYLE_PATH.into(),
        start_line,
        end_line,
    }
}

/// A prelocalized `4..=6` attempt delivered with `delivered` as the file,
/// then handed back to a native worker for the rework, as in production.
async fn prelocalized_delivery(db: &Database, repo: &Path, delivered: &str) -> (String, String) {
    std::fs::write(repo.join(STYLE_PATH), STYLE_BASE).unwrap();
    git(repo, &["add", STYLE_PATH]);
    git(repo, &["commit", "-m", "style"]);
    let (_task_ref, parent_id, _child_id, exec_id) = attached_cli_worker(db, repo).await;
    let (id, scope) = (
        exec_id.clone(),
        serde_json::to_string(&style_scope(4, 6)).unwrap(),
    );
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE task_executions SET worker_scope_json = ?2 WHERE id = ?1",
            rusqlite::params![id, scope],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    let path = managed_worktree_path(db, &exec_id).await;
    std::fs::write(Path::new(&path).join(STYLE_PATH), delivered).unwrap();
    git(
        Path::new(&path),
        &["commit", "-s", "-am", "style: round one"],
    );
    let manifest = manifest_json_with_files_for_dod(
        &git_rev(Path::new(&path), "HEAD"),
        serde_json::json!([{ "path": STYLE_PATH, "kind": "modified" }]),
        &dod_id_for_execution(db, &exec_id).await,
        true,
    );
    let delivered = deliver_worker_manifest(db, &exec_id, "ClaudeCode", "sess-a", &manifest)
        .await
        .unwrap();
    assert!(matches!(delivered, DeliverOutcome::Delivered { .. }));
    let id = exec_id.clone();
    db.with_conn(move |conn| {
        conn.execute(
            "UPDATE task_executions SET worker_target_kind = 'agent', \
                     worker_cli_session_id = NULL, worker_agent_type = 'Ollama' WHERE id = ?1",
            [&id],
        )?;
        Ok(())
    })
    .await
    .unwrap();
    seed_cli_session(db, 102, &parent_id, "sess-b").await;
    (exec_id, path)
}

#[tokio::test]
async fn request_changes_reanchors_a_prelocalized_range_after_a_delivery_that_added_lines() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    // Round one rewrote 4..=6 as five lines, with an orphan brace.
    let grown = ".tc-justin {\n  display: flex;\n}\n\
            .tc-justin__title {\n  margin: 0;\n  padding: 0;\n}\n}\n"
        .to_string()
        + STYLE_NEIGHBOUR;
    let (exec_id, path) = prelocalized_delivery(&db, repo.path(), &grown).await;

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_request_changes("remove the orphan brace"),
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    assert!(
        matches!(
            outcome,
            ReviewOutcome::Reviewed {
                verdict: ReviewVerdict::RequestChanges,
                ..
            }
        ),
        "{outcome:?}"
    );
    let execution = exec_of(&db, &exec_id).await;
    assert_eq!(execution.worker_scope, Some(style_scope(4, 8)));
    assert_eq!(
        event_count(&db, &exec_id, "worker_scope_reanchored").await,
        1
    );
    let findings_id = format!("orch-review-findings:{exec_id}:0");
    let findings: String = db
        .with_conn(move |conn| {
            Ok(conn.query_row(
                "SELECT content FROM messages WHERE id = ?1",
                [findings_id],
                |row| row.get(0),
            )?)
        })
        .await
        .unwrap();
    assert!(
        findings.contains("`4..=8`") && findings.contains("`4..=6`"),
        "the rework must be told the range moved: {findings}"
    );

    // The rework edits exactly the re-anchored range: the neighbour survives.
    let worktree = Path::new(&path);
    let receipt =
        crate::api::agent_workspace_tools::read_file_payload(worktree, STYLE_PATH, None, None)
            .unwrap()["content_sha256"]
            .as_str()
            .unwrap()
            .to_string();
    crate::api::agent_workspace_tools::edit_lines_payload(
        worktree,
        STYLE_PATH,
        4,
        8,
        ".tc-justin__title {\n  margin: 0;\n  padding: 0;\n}\n",
        &receipt,
    )
    .unwrap();
    let reworked = std::fs::read_to_string(worktree.join(STYLE_PATH)).unwrap();
    assert!(reworked.ends_with(STYLE_NEIGHBOUR), "{reworked}");
    assert_eq!(reworked.matches('}').count(), 3, "{reworked}");

    // Every later round maps from the launch range, not the previous one.
    let reanchored = reanchor_execution_scope(&db, &exec_of(&db, &exec_id).await)
        .await
        .unwrap()
        .expect("still moved from the launch range");
    assert_eq!(reanchored.original, style_scope(4, 6));
    assert_eq!(reanchored.current, style_scope(4, 7));
    assert_eq!(
        exec_of(&db, &exec_id).await.worker_scope,
        Some(style_scope(4, 7))
    );
}

#[tokio::test]
async fn request_changes_refuses_a_stale_prelocalized_range_naming_both_ranges() {
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    // Round one also touched the neighbouring rule, outside its range.
    let outside = STYLE_BASE.replace("red, blue", "red, green");
    let (exec_id, _path) = prelocalized_delivery(&db, repo.path(), &outside).await;

    let outcome = decide_review(
        &db,
        &exec_id,
        &review_request_changes("adjust the title"),
        "ClaudeCode",
        "sess-b",
    )
    .await
    .unwrap();
    let detail = match outcome {
        ReviewOutcome::StaleScope(detail) => detail,
        other => panic!("a stale range must refuse the rework, got {other:?}"),
    };
    assert!(
        detail.contains("stale range")
            && detail.contains("lines 4-6")
            && detail.contains("observed change: lines 8")
            && detail.contains("relaunch with a new worker_scope"),
        "{detail}"
    );
    let execution = exec_of(&db, &exec_id).await;
    assert_eq!(execution.status, TaskExecutionStatus::AwaitingReview);
    assert_eq!(execution.worker_scope, Some(style_scope(4, 6)));
    assert_eq!(
        count(
            &db,
            "SELECT COUNT(*) FROM messages WHERE id LIKE 'orch-review-findings:%'"
        )
        .await,
        0
    );
    let response = review_outcome_to_response(ReviewOutcome::StaleScope(detail));
    assert_eq!(response.error_code.as_deref(), Some("conflict"));
}

#[tokio::test]
async fn resumed_prelocalized_worker_is_reanchored_or_refused() {
    let repo = init_repo();
    std::fs::write(repo.path().join(STYLE_PATH), STYLE_BASE).unwrap();
    git(repo.path(), &["add", STYLE_PATH]);
    git(repo.path(), &["commit", "-m", "style"]);
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let execution = provision_single_task_execution_with_scope_and_validations(
        &db,
        ProvisionInput {
            task_reference: task_ref.clone(),
            parent_discussion_id: parent_id.clone(),
            worker: MessageTarget::discussion_agent(AgentType::Ollama),
            base_rev: Some("main".into()),
            idempotency_key: Some("prelocalized-resume".into()),
        },
        Some(style_scope(4, 6)),
        Vec::new(),
    )
    .await
    .unwrap();
    let exec_id = execution.id.clone();
    let child = execution.sub_discussion_id.clone().unwrap();
    let dispatch = execution.dispatch_job_id.clone().unwrap();
    let e = exec_id.clone();
    db.with_conn(move |conn| {
        crate::db::agent_dispatch::mark_completed(conn, &dispatch)?;
        crate::db::orchestration::transition_execution(
            conn,
            &e,
            TaskExecutionStatus::Interrupted,
            &backend_actor(),
            serde_json::json!({}),
        )?;
        Ok(())
    })
    .await
    .unwrap();
    // The interrupted worker had already replaced 4..=6 with one line.
    let path = managed_worktree_path(&db, &exec_id).await;
    let shrunk = ".tc-justin {\n  display: flex;\n}\n.tc-justin__title { margin: 0; }\n"
        .to_string()
        + STYLE_NEIGHBOUR;
    std::fs::write(Path::new(&path).join(STYLE_PATH), &shrunk).unwrap();

    wake_recovered_worker(&db, &exec_id).await.unwrap();
    assert_eq!(
        exec_of(&db, &exec_id).await.worker_scope,
        Some(style_scope(4, 4))
    );
    let message_id = format!("orch-resume-worker:{exec_id}:0");
    let notice: String = db
        .with_conn(move |conn| {
            Ok(conn.query_row(
                "SELECT content FROM messages WHERE id = ?1 AND discussion_id = ?2",
                rusqlite::params![message_id, child],
                |row| row.get(0),
            )?)
        })
        .await
        .unwrap();
    assert!(notice.contains("`4..=4`"), "{notice}");

    // An idempotent launch replay still compares with the launch scope.
    let replay = |scope: TaskWorkerScope| {
        let input = ProvisionInput {
            task_reference: task_ref.clone(),
            parent_discussion_id: parent_id.clone(),
            worker: MessageTarget::discussion_agent(AgentType::Ollama),
            base_rev: Some("main".into()),
            idempotency_key: Some("prelocalized-resume".into()),
        };
        provision_single_task_execution_with_scope_and_validations(
            &db,
            input,
            Some(scope),
            Vec::new(),
        )
    };
    assert_eq!(replay(style_scope(4, 6)).await.unwrap().id, exec_id);
    let changed = replay(style_scope(4, 5)).await.unwrap_err();
    assert!(
        provision_error_parts(&changed)
            .1
            .contains("cannot change the persisted worker_scope"),
        "{changed:?}"
    );

    // A change above the range leaves nothing safe to replay.
    std::fs::write(
        Path::new(&path).join(STYLE_PATH),
        shrunk.replace("display: flex", "display: grid"),
    )
    .unwrap();
    let error = wake_recovered_worker(&db, &exec_id).await.unwrap_err();
    let stale = error
        .downcast_ref::<StaleWorkerScope>()
        .unwrap_or_else(|| panic!("expected a stale-range refusal, got {error:#}"));
    assert!(
        stale.0.contains("lines 4-6") && stale.0.contains("observed change: lines 2"),
        "{stale}"
    );
}

#[test]
fn prelocalized_range_follows_only_changes_confined_to_it() {
    let scope = style_scope(4, 6);
    let base = STYLE_BASE.as_bytes();
    assert_eq!(
        reanchor_worker_scope(&scope, base, Some(base)).unwrap(),
        scope
    );
    let grown = STYLE_BASE.replace("margin: 0;\n", "margin: 0;\n  padding: 0;\n  gap: 0;\n");
    assert_eq!(
        reanchor_worker_scope(&scope, base, Some(grown.as_bytes())).unwrap(),
        style_scope(4, 8)
    );

    let refusal = |current: Option<&str>| {
        reanchor_worker_scope(&scope, base, current.map(str::as_bytes))
            .unwrap_err()
            .0
    };
    let emptied = STYLE_BASE.replace(".tc-justin__title {\n  margin: 0;\n}\n", "");
    let detail = refusal(Some(&emptied));
    assert!(
        detail.contains("removed every line") && detail.contains("lines 4-6"),
        "{detail}"
    );
    let appended = STYLE_BASE.to_string() + ".extra {}\n";
    assert!(
        refusal(Some(&appended)).contains("observed change: lines 10"),
        "a change after the range is outside it too"
    );
    assert!(refusal(None).contains("no longer exists"));
    let huge = STYLE_BASE.replace("margin: 0;\n", &"  margin: 0;\n".repeat(250));
    assert!(refusal(Some(&huge)).contains("now spans lines 4-255"));

    let anchor = TaskWorkerScope::PrelocalizedInsertAfter {
        path: STYLE_PATH.into(),
        anchor_line: 4,
    };
    let inserted = STYLE_BASE.replace(".tc-justin__title {\n", ".tc-justin__title {\n  gap: 0;\n");
    assert_eq!(
        reanchor_worker_scope(&anchor, base, Some(inserted.as_bytes())).unwrap(),
        anchor
    );
    let above = STYLE_BASE.replace("display: flex", "display: grid");
    let detail = reanchor_worker_scope(&anchor, base, Some(above.as_bytes()))
        .unwrap_err()
        .0;
    assert!(
        detail.contains("anchor line 4") && detail.contains("observed change: lines 2"),
        "{detail}"
    );
}

/// Both handoffs — the wake and the reassignment — must match what the
/// execution has actually produced. The reassignment wording used to
/// declare the manifests authoritative unconditionally, which sent a worker
/// that had delivered nothing back to inventory an empty state.
#[test]
fn a_handoff_matches_what_the_execution_has_produced() {
    let started_over = handoff_notice(false, None);
    assert!(
        started_over.starts_with("**Démarre la tâche**"),
        "{started_over}"
    );
    assert!(
        !started_over.contains("autoritatifs"),
        "nothing is authoritative yet: {started_over}"
    );
    assert!(
        started_over.contains("offset"),
        "the slice hint must survive: {started_over}"
    );

    let resumed = handoff_notice(true, None);
    assert!(resumed.starts_with("**Reprise**"), "{resumed}");
    assert!(resumed.contains("l'étape inachevée"), "{resumed}");

    let reassigned_cold = handoff_notice(false, Some(4));
    assert!(
        reassigned_cold.starts_with("**Démarre la tâche — génération 4**"),
        "{reassigned_cold}"
    );
    assert!(
        !reassigned_cold.contains("Ne recommence que l'étape inachevée"),
        "generation 4 of a delivery-less execution has no unfinished step: {reassigned_cold}"
    );

    let reassigned_warm = handoff_notice(true, Some(4));
    assert!(
        reassigned_warm.starts_with("**Reprise — génération 4**"),
        "{reassigned_warm}"
    );
    assert!(
        reassigned_warm.contains("autoritatifs"),
        "{reassigned_warm}"
    );
}

#[tokio::test]
async fn handoff_with_dirty_worktree_tells_worker_to_commit() {
    // KT-404: dirty worktree → explicit message to review diff and commit
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let exec = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("kt-404-dirty".into()),
        },
    )
    .await
    .unwrap();

    // Dirty the exact managed workspace persisted by provisioning. Recomputing
    // its layout here can point at a sibling path and make this regression test
    // pass without exercising the handoff inspection at all.
    let workspace_exec_id = exec.id.clone();
    let workspace_path = db
        .with_conn(move |conn| {
            let workspace = crate::db::discussion_workspaces::get_managed_for_execution(
                conn,
                &workspace_exec_id,
            )?
            .context("managed workspace missing")?;
            workspace.canonical_path.context("canonical path missing")
        })
        .await
        .expect("managed workspace must exist after provisioning");
    std::fs::write(
        std::path::Path::new(&workspace_path).join("dirty.txt"),
        "uncommitted",
    )
    .unwrap();

    let exec_id = exec.id.clone();
    let msg = db
        .with_conn(move |conn| {
            Ok(handoff_notice_with_context(
                false,
                None,
                Some(conn),
                Some(&exec_id),
            ))
        })
        .await
        .unwrap();

    assert!(
        msg.contains("Du travail non commité"),
        "must name dirty state: {msg}"
    );
    assert!(msg.contains("git_diff"), "must ask to review diff");
    assert!(msg.contains("git_commit"), "must ask to commit");
    assert!(
        !msg.contains("aucun travail n'a"),
        "must NOT claim empty state: {msg}"
    );
}

/// KT-1408 — the limit stopped a worker with a dirty worktree: Kronn
/// checkpoints it, and the resume handoff names the commit and the time the
/// generation ran instead of claiming that no work was recorded.
#[tokio::test]
async fn handoff_after_a_limit_stop_names_the_wip_checkpoint_and_the_elapsed_time() {
    use crate::api::worker_time_limit::{checkpoint_worktree, record_stop_event};
    let repo = init_repo();
    let db = Database::open_in_memory().unwrap();
    let (task_ref, parent_id, _) = seed(&db, repo.path()).await;
    let exec = provision_single_task_execution(
        &db,
        ProvisionInput {
            task_reference: task_ref,
            parent_discussion_id: parent_id,
            worker: native_worker(),
            base_rev: Some("main".into()),
            idempotency_key: Some("kt-1408-limit".into()),
        },
    )
    .await
    .unwrap();
    let workspace_exec_id = exec.id.clone();
    let workspace_path = db
        .with_conn(move |conn| {
            crate::db::discussion_workspaces::get_managed_for_execution(conn, &workspace_exec_id)?
                .and_then(|workspace| workspace.canonical_path)
                .context("managed workspace missing")
        })
        .await
        .unwrap();
    std::fs::write(
        std::path::Path::new(&workspace_path).join("half-done.txt"),
        "uncommitted",
    )
    .unwrap();
    let limit = std::time::Duration::from_secs(120 * 60);
    let checkpoint = checkpoint_worktree(
        std::path::Path::new(&workspace_path),
        "KT-1408",
        limit,
        limit,
        None,
    )
    .unwrap()
    .expect("the dirty worktree is checkpointed");
    let commit = checkpoint.commit.clone().expect("a WIP commit");
    assert!(
        crate::core::worktree::worktree_dirty_files(std::path::Path::new(&workspace_path))
            .unwrap()
            .is_empty()
    );

    let exec_id = exec.id.clone();
    let (fr, en) = db
        .with_conn(move |conn| {
            record_stop_event(
                conn,
                &exec_id,
                "dispatch-1",
                limit,
                limit,
                Some(&checkpoint),
            )?;
            Ok((
                handoff_notice_in(RoomLang::Fr, false, Some(2), Some(conn), Some(&exec_id)),
                handoff_notice_in(RoomLang::En, false, Some(2), Some(conn), Some(&exec_id)),
            ))
        })
        .await
        .unwrap();

    assert!(fr.contains("génération 1 : 120 min"), "{fr}");
    assert!(fr.contains(&commit), "{fr}");
    assert!(fr.contains("génération 2"), "{fr}");
    assert!(
        en.contains("generation 1: 120 min of the 120-min limit"),
        "{en}"
    );
    assert!(en.contains(&format!("WIP commit `{commit}`")), "{en}");
    assert!(
        !en.contains("No work has been recorded") && !fr.contains("Aucun travail n'a encore"),
        "a checkpointed generation is recorded work: {en}"
    );
}

/// KT-1408 — the brief tells a spawned CLI worker its tool results carry the
/// time-limit notice; a worker that commits itself has neither tool.
#[test]
fn the_cli_worker_brief_announces_the_time_limit_notice() {
    let brief = |lang, shell, projection| {
        worker_brief_markdown_in(
            lang,
            "KT-1408",
            "Limit",
            "desc",
            &[],
            "/wt",
            "branch",
            "abc",
            shell,
            projection,
            None,
            true,
        )
    };
    let en = brief(RoomLang::En, true, true);
    assert!(en.contains("`time_limit` notice"), "{en}");
    assert!(en.contains("checkpointed (WIP)"), "{en}");
    let fr = brief(RoomLang::Fr, true, true);
    assert!(fr.contains("avis `time_limit`"), "{fr}");
    for self_committing in [
        brief(RoomLang::En, false, false),
        brief(RoomLang::Fr, true, false),
    ] {
        assert!(!self_committing.contains("time_limit"), "{self_committing}");
    }
}

